    def test_a_gap_fills_ledger_row_is_given_its_albums_name(self):
        """A gap fill's ledger row is written under the release id alone. The
        fills answer names it from the review group with that release, marks it
        `gapFill`, and leaves a row that has its own name, or no group, alone."""
        saved = dict(bot._album_fill_status)
        try:
            with isolated_review():
                with bot._review_lock:
                    g = self._origin_group("g1", "library", album="Ursgal")
                    g.update(artist="Enji", canonical_mbid="rel-gap", canonical_album_id="nd-1")
                    bot._review_state["groups"] = [g]
                with bot._album_fill_lock:
                    bot._album_fill_status.clear()
                    bot._album_fill_status.update({
                        "rel-gap": {"state": "verified", "done": 8, "total": 8, "updated_at": 3.0},
                        "rel-own": {"state": "placed", "artist": "After", "album": "After EP",
                                    "rgid": "rg", "updated_at": 2.0},
                        "rel-lost": {"state": "placed", "updated_at": 1.0},
                    })
                with patch.object(bot, "_nd_album_artist_map", lambda: {}):
                    albums = bot._fills_view(["rel-gap", "rel-own", "rel-lost", "rel-none"], [])["albums"]
            self.assertEqual((albums["rel-gap"]["artist"], albums["rel-gap"]["album"]), ("Enji", "Ursgal"))
            self.assertEqual((albums["rel-gap"]["groupId"], albums["rel-gap"]["albumId"]), ("g1", "nd-1"))
            self.assertTrue(albums["rel-gap"]["gapFill"])
            self.assertEqual(albums["rel-own"]["album"], "After EP")
            self.assertNotIn("gapFill", albums["rel-own"])
            self.assertEqual((albums["rel-lost"]["album"], albums["rel-lost"]["artist"]), ("", ""))
            self.assertEqual(albums["rel-none"]["state"], "unknown")
            self.assertEqual(albums["rel-none"]["album"], "")
        finally:
            with bot._album_fill_lock:
                bot._album_fill_status.clear()
                bot._album_fill_status.update(saved)

    def test_active_gap_fills_count_the_album_not_what_is_left(self):
        """A finished file leaves the transfer list, so progress worked out from
        the transfers alone restarts after every file. `_active_gap_fills`
        carries the gap's own counts (done / failed / total) plus the files'
        worth still in flight, and reading the group marks nothing dirty."""
        group = {"id": "g1", "artist": "A", "album": "Alb", "origin": "library",
                 "missing_tracks": [], "present": 1, "total": 5}
        frame = {"album": "Alb", "artist": "A", "done": 2, "failed": 1, "total": 4}
        transfers = [
            {"id": "t1", "kind": "track", "state": "active", "pct": 50, "groupId": "g1", "username": "peer"},
            {"id": "t2", "kind": "track", "state": "queued", "pct": 0, "groupId": "g1", "username": "peer"},
            {"id": "t3", "kind": "track", "state": "done", "pct": 100, "groupId": "g1"},
            {"id": "t4", "kind": "album", "state": "active", "pct": 70, "groupId": ""},
            {"id": "t5", "kind": "track", "state": "active", "pct": 10, "groupId": "gone"},
        ]
        with isolated_review():
            with bot._review_lock:
                bot._review_state["groups"] = [group]
            marked = []
            with patch.object(bot, "_gap_fill_frame", lambda g: dict(frame)), \
                 patch.object(bot, "_mark_review_groups_dirty", lambda *a, **k: marked.append(a)):
                fills = bot._active_gap_fills(transfers)
        self.assertEqual(fills, [{"groupId": "g1", "album": "Alb", "artist": "A",
                                  "done": 2, "failed": 1, "total": 4, "partial": 0.5,
                                  "active": 1, "queued": 1, "peer": "peer"}])
        self.assertEqual(marked, [], "a read on every poll must not queue a row write")

