    # -- caching -------------------------------------------------------------

    def test_a_hit_is_cached_and_the_second_call_asks_nobody(self):
        with patch("listenbrainz_bot.mbz_get") as mbz, \
             patch("listenbrainz_bot._wiki_get",
                   side_effect=self._wiki_responses()) as wiki:
            mbz.side_effect = lambda path, params=None, **kw: (
                self.URL_RELS if params and params.get("inc") == "url-rels" else {})
            first = bot.meta_for_artist("a-mbid")
            calls_after_first = (mbz.call_count, wiki.call_count)
            second = bot.meta_for_artist("a-mbid")
            self.assertEqual((mbz.call_count, wiki.call_count), calls_after_first)
        self.assertEqual(first["summary"], second["summary"])

    def test_refresh_bypasses_the_cache(self):
        with patch("listenbrainz_bot.mbz_get") as mbz, \
             patch("listenbrainz_bot._wiki_get", side_effect=self._wiki_responses()):
            mbz.side_effect = lambda path, params=None, **kw: (
                self.URL_RELS if params and params.get("inc") == "url-rels" else {})
            bot.meta_for_artist("a-mbid")
            before = mbz.call_count
            bot.meta_for_artist("a-mbid", refresh=True)
            self.assertGreater(mbz.call_count, before)

    def test_a_miss_is_cached_too_but_expires_sooner(self):
        """"No article" must not cost a MusicBrainz second on every page open —
        and must still be re-asked well before a hit would be."""
        with patch("listenbrainz_bot.mbz_get", return_value={}) as mbz, \
             patch("listenbrainz_bot._wiki_get", return_value={}):
            bot.meta_for_artist("obscure")
            self.assertEqual(mbz.call_count, 2)   # url-rels + artist-rels
            bot.meta_for_artist("obscure")
            self.assertEqual(mbz.call_count, 2)   # served from the negative cache

        conn = bot._index_db()
        row = conn.execute(
            "SELECT ok, fetched_at FROM meta WHERE kind='artist' AND mbid='obscure'"
        ).fetchone()
        self.assertEqual(row["ok"], 0)
        # Age it past the negative TTL but well inside the positive one.
        aged = time.time() - (bot.META_TTL_EMPTY + 60)
        self.assertLess(bot.META_TTL_EMPTY + 60, bot.META_TTL_OK)
        conn.execute("UPDATE meta SET fetched_at = ? WHERE mbid = 'obscure'", (aged,))
        conn.commit()
        self.assertIsNone(bot._meta_cache_read("artist", "obscure"))

    def test_a_hit_survives_past_the_negative_ttl(self):
        with patch("listenbrainz_bot.mbz_get") as mbz, \
             patch("listenbrainz_bot._wiki_get", side_effect=self._wiki_responses()):
            mbz.side_effect = lambda path, params=None, **kw: (
                self.URL_RELS if params and params.get("inc") == "url-rels" else {})
            bot.meta_for_artist("a-mbid")
        conn = bot._index_db()
        conn.execute("UPDATE meta SET fetched_at = ?",
                     (time.time() - (bot.META_TTL_EMPTY + 60),))
        conn.commit()
        self.assertIsNotNone(bot._meta_cache_read("artist", "a-mbid"))

    # -- a refresh must never destroy a good About (I-020) ---------------------

    MEMBERS = {"relations": [{"type": "member of band", "direction": "backward",
                              "artist": {"id": "m-1", "name": "Thom Yorke"}}]}

    def _mbz_up(self, path, params=None, **kw):
        inc = (params or {}).get("inc", "")
        return self.URL_RELS if inc == "url-rels" else self.MEMBERS if inc == "artist-rels" else {}

    @staticmethod
    def _mbz_down(path, params=None, strict=False, **kw):
        """MusicBrainz in an outage, as `mbz_get` reports one: {} to a
        fail-soft caller, an exception to a strict one."""
        if strict:
            raise bot.MusicBrainzUnavailable("MusicBrainz did not answer (HTTP 503)")
        return {}

    def _stored_about(self):
        """A good About in the cache, as a first read stores it."""
        with patch("listenbrainz_bot.mbz_get", side_effect=self._mbz_up), \
             patch("listenbrainz_bot._wiki_get", side_effect=self._wiki_responses()):
            stored = bot.meta_for_artist("a-mbid", refresh=True)
        self.assertTrue(stored["summary"] and stored["relations"]["members"])
        return stored

    def _assert_about_kept(self, stored):
        """Still in the cache, and an ordinary read serves it asking nobody."""
        self.assertEqual(bot._meta_cache_read("artist", "a-mbid"), stored)
        with patch("listenbrainz_bot.mbz_get", side_effect=AssertionError("asked MusicBrainz")), \
             patch("listenbrainz_bot._wiki_get", side_effect=AssertionError("asked Wikipedia")):
            payload, status = bot._meta_artist_view("a-mbid", "")
        self.assertEqual((status, payload["found"], payload["summary"]),
                         (200, True, stored["summary"]))

    def test_a_refresh_during_a_musicbrainz_outage_is_502_and_keeps_the_about(self):
        """It used to build an empty About from the `{}` an outage answers,
        write it over the stored one and say 200 `found: false` — which the
        hub then kept for six hours and both clients showed."""
        stored = self._stored_about()
        with patch("listenbrainz_bot.mbz_get", side_effect=self._mbz_down), \
             patch("listenbrainz_bot._wiki_get", side_effect=self._wiki_responses()):
            payload, status = bot._meta_artist_view("a-mbid", "", refresh=True)
        self.assertEqual(status, 502)
        self.assertIs(payload["retryable"], True)
        self.assertTrue(payload["error"])
        self.assertNotIn("found", payload)
        self._assert_about_kept(stored)

    def test_a_refresh_while_wikipedia_does_not_answer_is_502_and_keeps_the_about(self):
        stored = self._stored_about()

        class Answer:
            def __init__(self, body):
                self.body = body

            def raise_for_status(self):
                pass

            def json(self):
                return self.body

        failures = {
            "the request fails": OSError("connection reset"),
            "an error body under a 200": Answer({"error": {"code": "maxlag", "info": "lagged"}}),
            "not an object at all": Answer([]),
        }
        for label, failure in failures.items():
            with self.subTest(label):
                bot._wiki_cache.clear()
                with patch("listenbrainz_bot.mbz_get", side_effect=self._mbz_up), \
                     patch.object(bot._http, "get", side_effect=[failure]
                                  if isinstance(failure, Exception) else None,
                                  return_value=failure):
                    payload, status = bot._meta_artist_view("a-mbid", "", refresh=True)
                self.assertEqual((status, payload.get("retryable")), (502, True))
                self.assertEqual(bot._wiki_cache, {}, "a failure is not remembered as an answer")
                self._assert_about_kept(stored)

    def test_a_refresh_with_one_leg_missing_does_not_store_the_rest(self):
        """The members and the credits are legs too: stored without them, a
        good About lost its line-up to one failed request."""
        stored = self._stored_about()
        for leg, inc in (("the links and the article's address", "url-rels"),
                         ("the members", "artist-rels")):
            def one_down(path, params=None, strict=False, **kw):
                if (params or {}).get("inc") == inc:
                    return self._mbz_down(path, params, strict=strict)
                return self._mbz_up(path, params)

            with self.subTest(down=leg):
                with patch("listenbrainz_bot.mbz_get", side_effect=one_down), \
                     patch("listenbrainz_bot._wiki_get", side_effect=self._wiki_responses()):
                    payload, status = bot._meta_artist_view("a-mbid", "", refresh=True)
                self.assertEqual((status, payload.get("retryable")), (502, True))
                self._assert_about_kept(stored)

    def test_a_refresh_that_finds_nothing_stores_and_answers_found_false(self):
        """The sources answered, and had nothing: that is an answer."""
        answers = {
            "no relations at all": lambda path, params=None, **kw: (
                {"name": "Radiohead", "relations": []}
                if (params or {}).get("inc") == "url-rels" else {"relations": []}),
            "no such artist": None,
        }
        for label, mbz in answers.items():
            with self.subTest(label):
                self._stored_about()

                def gone(path, params=None, strict=False, **kw):
                    if strict:
                        raise bot.MusicBrainzNoSuchEntity("MusicBrainz 404")
                    return {}

                with patch("listenbrainz_bot.mbz_get", side_effect=mbz or gone), \
                     patch("listenbrainz_bot._wiki_get",
                           side_effect=self._wiki_responses(has_article=False, description="")):
                    payload, status = bot._meta_artist_view("a-mbid", "", refresh=True)
                self.assertEqual((status, payload["found"], payload["summary"]), (200, False, ""))
                self.assertEqual(payload["relations"], {"members": [], "related": []})
                kept = bot._meta_cache_read("artist", "a-mbid")
                self.assertEqual((kept["summary"], kept["relations"]["members"]), ("", []))

    def test_a_refresh_with_no_article_keeps_what_else_there_is(self):
        """Wikipedia answering "no such page" is an answer, not a failure."""
