        rows = self._rows()
        self.assertEqual(rows[0]["decision"], "placed")
        self.assertTrue(os.path.isfile(stranger), "the unrelated file stays put")
        self.assertEqual(rows[2]["decision"], "downloaded")
        self.assertNotIn("download_error", rows[2])

