        self.assertTrue(bot._index_store_unresolved_artist("Untagged", "nd-2"))
        payload, status = self.set_override("nd-2", name="")
        self.assertEqual((status, payload["name"]), (200, "Untagged"),
                         "no name sent: Navidrome's own")
