    def test_a_filled_album_does_move_into_a_row_no_other_library_artist_holds(self):
        """The exception is for another artist's row only: the artist's own
        row under the new key, and one whose holder left the library (the
        override's scan takes that over), both take the fill mark."""
        for holder in ("nd-1", "nd-gone"):
            with self.subTest(holder=holder), isolated_review():
                self.store(self.TAG, "nd-1", [self.rel("rg-a", "A")])
