    def test_a_filled_album_is_not_written_into_a_live_holders_row_fresh_or_not(self):
        """The skip is about whose row it is, not about whether a scan follows:
        a stale row of a live holder is taken over by the override's scan, and
        the marks are still not written into it first."""
        self.library.append({"id": "nd-9", "name": "Nirvana UK", "musicBrainzId": self.PICK})
        for fresh in (True, False):
            with self.subTest(fresh=fresh), isolated_review():
                self.scans.clear()
                self.store(self.TAG, "nd-1", [self.rel("rg-a", "A")])
                self.assertEqual(bot._index_mark_release_present(rgid="rg-a"), 1)
                self.store(self.PICK, "nd-9", [self.rel("rg-a", "A")], name="Nirvana UK")
                if not fresh:
                    with bot._index_lock, bot._index_db() as conn:
                        conn.execute("UPDATE artists SET scanned_at = 0 WHERE artist_key = ?",
                                     (self.PICK,))
                payload, status = self.set_override()
                self.assertEqual(status, 200)
                self.assertEqual(bool(payload["task_id"]), not fresh,
                                 "a fresh row is covered; a stale one is rescanned")
                self.assertEqual([(r["rgid"], r["status"])
                                  for r in bot._index_get_artist(self.PICK, "")["releases"]],
                                 [("rg-a", "missing")])

