    # -- a fill in flight ----------------------------------------------------

    def _fills(self):
        """(what is in flight, how to arrange it) for the artist `nd-1` =
        "Nirvana", whose index row lists `rg-dl` and the gap group `g-1`."""
        soon = time.time() + 30
        return (
            ("an album fill downloading one of its release-groups", lambda:
                bot._album_fill_status.update(r1={"state": "downloading", "rgid": "rg-dl",
                                                  "artist": "Nirvana (US)"})),
            ("an album fill still searching, known only by the artist's name", lambda:
                bot._album_fill_status.update(r1={"state": "searching", "rgid": "rg-fresh",
                                                  "artist": "NIRVANA"})),
            ("an album fill being placed", lambda:
                bot._album_fill_status.update(r1={"state": "placing", "rgid": "rg-dl"})),
            ("an album fill placed and not yet verified", lambda:
                bot._album_fill_status.update(r1={"state": "placed", "rgid": "rg-dl"})),
            ("a failed fill whose automatic retry is pending", lambda:
                bot._album_fill_status.update(r1={"state": "failed", "rgid": "rg-dl",
                                                  "retryAt": soon})),
            ("a live transfer group with no ledger row", lambda:
                bot.pending_album_groups.update(ag1={"artist": "nirvana", "album": "Bleach"})),
            ("a gap fill's live transfer, by the index row's group", lambda:
                bot.pending_downloads.update({("peer", "a.flac"): {
                    "review_group_id": "g-1", "review_track_index": 0}})),
            ("a gap fill's live transfer, by the group's artist", lambda:
                bot.pending_downloads.update({("peer", "a.flac"): {
                    "review_group_id": "g-name", "review_track_index": 0}})),
            ("a placement verifier still running", lambda:
                bot._placement_verifiers.add("g-1")),
        )

    @contextlib.contextmanager
    def _clean_registries(self):
        with patch.dict(bot._album_fill_status, {}, clear=True), \
                patch.dict(bot.pending_album_groups, {}, clear=True), \
                patch.dict(bot.pending_downloads, {}, clear=True), \
                patch.object(bot, "_placement_verifiers", set()):
            yield

    def _busy_world(self):
        self.store(self.TAG, "nd-1", [self.rel("rg-dl", "Bleach"),
                                      self.rel("rg-gap", "Nevermind", "incomplete",
                                               group_id="g-1")])
        with bot._review_lock:
            bot._review_state["groups"] = [
                AlbumReviewTests._origin_group("g-1", "library", artist="Nirvana"),
                AlbumReviewTests._origin_group("g-name", "library", artist="Nirvana"),
                AlbumReviewTests._origin_group("g-else", "library", artist="Someone Else")]

    def test_set_is_409_busy_while_a_fill_for_the_artist_is_in_flight(self):
        self._busy_world()
        for label, arrange in self._fills():
            with self.subTest(label), self._clean_registries():
                arrange()
                payload, status = self.set_override()
                self.assertEqual((status, payload.get("code")), (409, "busy"))
                self.assertTrue(payload["error"])
                self.assertEqual(self.overrides(), [])
                self.assertEqual(self.holders(), {self.TAG: "nd-1"})
        self.assertEqual(self.scans, [])

    def test_remove_is_409_busy_while_a_fill_for_the_artist_is_in_flight(self):
        self._busy_world()
        self.seed("nd-1", self.PICK)
        for label, arrange in self._fills():
            with self.subTest(label), self._clean_registries():
                arrange()
                payload, status = bot._remove_artist_override("nd-1")
                self.assertEqual((status, payload.get("code")), (409, "busy"))
                self.assertTrue(payload["error"])
                self.assertEqual(len(self.overrides()), 1)
        self.assertEqual(self.scans, [])

    def test_a_fill_that_is_over_or_is_someone_elses_does_not_block(self):
        self._busy_world()
        soon = time.time() + 30
        bot._album_fill_status.update(
            done={"state": "verified", "rgid": "rg-dl", "artist": "Nirvana"},
            gave_up={"state": "placed", "rgid": "rg-dl", "artist": "Nirvana",
                     "verifyGaveUp": True},
            failed={"state": "failed", "rgid": "rg-dl", "artist": "Nirvana", "retryAt": 0},
            stopped={"state": "cancelled", "rgid": "rg-dl", "artist": "Nirvana"},
            waiting={"state": "needs_match", "rgid": "rg-dl", "artist": "Nirvana"},
            other={"state": "downloading", "rgid": "rg-other", "artist": "Someone Else"},
            others_retry={"state": "failed", "rgid": "rg-other", "artist": "Someone Else",
                          "retryAt": soon})
        bot.pending_album_groups.update(
            ag1={"artist": "Someone Else", "album": "X"},
            ag2={"artist": "Nirvana", "album": "Bleach", "cancelled": True})
        bot.pending_downloads.update({("peer", "b.flac"): {
            "review_group_id": "g-else", "review_track_index": 0}})
        bot._placement_verifiers.add("g-else")
        # A `queued` row with no transfer behind it is a phantom the next
        # rescan resets, not a fill: it must not lock the artist.
        with bot._review_lock:
            bot._review_state["groups"][0]["missing_tracks"] = [
                {"title": "t", "decision": "queued"}]
        self.assertEqual(self.set_override()[1], 200)

