    # -- a scan that was already running --------------------------------------

    def test_a_scan_already_running_cannot_file_the_artist_back_after_a_set(self):
        old = {"artist_mbid": self.TAG, "artist_name": "Nirvana",
               "releases": [self.rel("rg-old")]}
