    def test_summary_days_and_hours_are_local_across_a_day_boundary_and_a_dst_change(self):
        self.load(self.fixture())
        s = self.summary("7d")
        self.assertEqual(s["daily"], [
            {"date": "2026-03-24", "count": 0}, {"date": "2026-03-25", "count": 1},
            {"date": "2026-03-26", "count": 0}, {"date": "2026-03-27", "count": 1},
            {"date": "2026-03-28", "count": 0},
            # 23:30 UTC on the 28th, 01:30 CET and 03:30 CEST are all the 29th.
            {"date": "2026-03-29", "count": 3}, {"date": "2026-03-30", "count": 2}])
        hours = [0] * 24
        for hour, n in ((0, 1), (1, 1), (3, 1), (9, 2), (10, 1), (22, 1)):
            hours[hour] = n
        self.assertEqual(s["hours"], hours)
        self.assertEqual(len(s["heatmap"]), 112)
        self.assertEqual(s["heatmap"][-1], {"date": "2026-03-30", "count": 2})
        self.assertEqual(s["heatmap"][0]["date"], "2025-12-09")
        self.assertEqual({d["date"]: d["count"] for d in s["heatmap"] if d["count"]},
                         {"2026-02-01": 1, "2026-03-25": 1, "2026-03-27": 1,
                          "2026-03-29": 3, "2026-03-30": 2},
                         "the heatmap does not depend on the period")
        # The same listens seen from UTC: the 23:30 one stays on the 28th,
        # and 03:30 CEST is 01:30.
        utc = self.summary("7d", tz="")
        self.assertEqual(utc["tz"], "UTC")
        self.assertEqual({d["date"]: d["count"] for d in utc["daily"] if d["count"]},
                         {"2026-03-25": 1, "2026-03-27": 1, "2026-03-28": 1,
                          "2026-03-29": 2, "2026-03-30": 2})
        self.assertEqual((utc["hours"][0], utc["hours"][1], utc["hours"][23]), (1, 1, 1))

    def test_summary_periods(self):
        self.load(self.fixture())
        self.assertEqual(self.summary("30d")["totals"]["plays"], 7)
        self.assertEqual(len(self.summary("30d")["daily"]), 30)
        ninety = self.summary("90d")
        self.assertEqual((ninety["totals"]["plays"], ninety["totals"]["seconds"]), (8, 1160))
        self.assertEqual(len(ninety["daily"]), 90)
        self.assertEqual(len(self.summary("365d")["daily"]), 90, "capped at the last 90 days")
        everything = self.summary("all")
        self.assertEqual(everything["totals"]["plays"], 8)
        self.assertEqual((everything["daily"][0]["date"], len(everything["daily"])),
                         ("2026-02-01", 58), "from the first listen's day to today")
        # Whole local days ending today, not the last 7 x 24 hours: at 08:00
        # on April 1st the listen of 10:00 on March 25th is outside.
        self.assertEqual(self.summary("7d", now=self.at(2026, 4, 1, 8, 0))["totals"]["plays"], 6)

    def test_streak_counts_local_days_from_today_or_from_yesterday(self):
        self.load(self.fixture())
        self.assertEqual(self.summary()["streak"], {"current": 2, "longest": 2})
        tomorrow = self.at(2026, 3, 31, 12, 0)
        self.assertEqual(self.summary(now=tomorrow)["streak"], {"current": 2, "longest": 2},
                         "no listen today yet: the streak that ended yesterday still stands")
        self.assertEqual(self.summary(now=self.at(2026, 4, 1, 12, 0))["streak"],
                         {"current": 0, "longest": 2})
        # In UTC the 23:30 listen fills the 28th: 27, 28, 29, 30 in a row.
        self.assertEqual(self.summary(tz="")["streak"], {"current": 4, "longest": 4})

