    def test_ownership_is_read_for_every_answer_not_cached_with_the_aggregate(self):
        """`owned` and the Navidrome ids change when the library does, not
        when a listen arrives; a cached "not in your library" would be the
        last stale one left, since the hub flushes its own on a library event."""
        self.load(self.fixture())
        self.index_library()
        third = lambda: next(a for a in self.summary()["topAlbums"] if a["title"] == "Third")
        self.assertEqual((third()["owned"], third()["ndAlbumId"]), (False, ""))
        rows, _ = bot._listening_unowned_view("7d", "album", "30", now=self.now)
        self.assertEqual([r["title"] for r in rows["rows"]], ["Third"])
        # The album lands and Gamma becomes a library artist; no new listen.
        self.library.append({"id": "nd-g", "name": "Gamma", "musicBrainzId": "a-3"})
        bot._ND_ARTIST_INDEX["ts"] = 0.0
        bot._index_store_artist({"artist_mbid": "a-3", "artist_name": "Gamma", "releases": [
            {"rgid": "rg-3", "title": "Third", "status": "complete",
             "navidrome_album_ids": ["al-3"]}]}, "nd-g")
        self.assertEqual((third()["owned"], third()["ndAlbumId"]), (True, "al-3"))
        self.assertEqual(self.summary()["topArtists"][2]["ndArtistId"], "nd-g")
        rows, _ = bot._listening_unowned_view("7d", "album", "30", now=self.now)
        self.assertEqual(rows["rows"], [])

    def test_an_album_the_library_holds_is_owned_whatever_the_index_knows(self):
        """`owned` is "the library holds it". The index alone called a held
        album not owned for every artist lb-bot never scanned, guessed
        wrongly or cannot bucket (non-Latin names) — and one client offers
        to acquire what this list calls not owned."""
        self.library += [{"id": "nd-k", "name": "Кино"}, {"id": "nd-s", "name": "椎名林檎"}]
        self.albums += [
            {"id": "al-k", "artistId": "nd-k", "artist": "Кино", "name": "Группа крови",
             "musicBrainzId": "rel-kino"},
            {"id": "al-s", "artistId": "nd-s", "artist": "椎名林檎", "name": "無罪モラトリアム"},
            {"id": "al-d", "artistId": "nd-d", "artist": "Delta", "name": "Fourth",
             "musicBrainzId": "REL-DELTA"}]
        t = self.at(2026, 3, 30, 7, 0)
        self.load([
            # By the Navidrome album's release MBID, whatever the text says.
            self.listen(t, "Hit", "Delta feat. Someone", "Fourth (2011 Remaster)",
                        {"artist_mbids": ["a-4"], "release_group_mbid": "rg-4",
                         "release_mbid": "rel-delta"}),
            # By the same artist and title, casefolded: Cyrillic and Japanese.
            self.listen(t + 60, "Песня", "КИНО", "группа КРОВИ",
                        {"artist_mbids": ["a-k"], "release_group_mbid": "rg-k"}),
            self.listen(t + 120, "歌", "椎名林檎", "無罪モラトリアム",
                        {"artist_mbids": ["a-s"], "release_group_mbid": "rg-s"}),
            # An empty half never matches: no title, and Кино holds an album.
            self.listen(t + 180, "Без альбома", "Кино", "",
                        {"artist_mbids": ["a-k"], "release_group_mbid": "rg-k2"}),
            # Not in the library by any of the three.
            self.listen(t + 240, "X", "Кино", "Звезда по имени Солнце",
                        {"artist_mbids": ["a-k"], "release_group_mbid": "rg-k3"})])
        albums = {a["rgid"]: (a["owned"], a["ndAlbumId"]) for a in self.summary()["topAlbums"]}
        self.assertEqual(albums, {"rg-4": (True, "al-d"), "rg-k": (True, "al-k"),
                                  "rg-s": (True, "al-s"), "rg-k2": (False, ""),
                                  "rg-k3": (False, "")})
        payload, code = bot._listening_unowned_view("7d", "album", "30", now=self.now)
        self.assertEqual((code, sorted(r["rgid"] for r in payload["rows"])),
                         (200, ["rg-k2", "rg-k3"]))
        recent = {r["rgid"]: r["ndAlbumId"]
                  for r in bot._listening_recent_view("", "", now=self.now)[0]["rows"]}
        self.assertEqual(recent, {"rg-4": "al-d", "rg-k": "al-k", "rg-s": "al-s",
                                  "rg-k2": "", "rg-k3": ""})

