    def test_the_title_key_of_an_all_latin_name_is_the_indexs_own(self):
        """Nothing changes where the normalised key already told titles
        apart: punctuation and edition words are still ignored."""
        for artist, title in (("Daft Punk", "Random Access Memories (Deluxe Edition)"),
                              ("AC/DC", "Back in Black"), ("!!!", "Louden Up Now"),
                              ("Sigur Rós", "( )")):
            with self.subTest(artist=artist, title=title):
                if (artist + title).isascii():
                    expected = []
                    for norm in (bot._norm_album_text, bot._fuzzy_album_text):
                        a, b = norm(artist), norm(title)
                        if a and b and f"{a}|{b}" not in expected:
                            expected.append(f"{a}|{b}")
                    self.assertEqual(list(bot._listens_title_key_pair(artist, title)), expected)
                else:
                    self.assertEqual(bot._listens_title_key_pair(artist, title), ())
        self.assertEqual(bot._listens_title_key_pair("Beyoncé", "Lemonade (Deluxe Edition)"),
                         ("beyoncé|lemonade deluxe edition", "beyoncé|lemonade"))
        nfd = "Beyonce\u0301"
        self.assertEqual(bot._listens_title_key_pair(nfd, "Lemonade"),
                         bot._listens_title_key_pair("BEYONCÉ", "lemonade!"))
        # A vowel sign is a mark, not a letter, and is the whole difference here.
        self.assertNotEqual(bot._listens_title_key_pair("X", "कि"),
                            bot._listens_title_key_pair("X", "की"))
        # A curly apostrophe is punctuation in either script.
        self.assertEqual(bot._listens_title_key_pair("Daft Punk", "Don\u2019t Stop"),
                         bot._listens_title_key_pair("Daft Punk", "Don't Stop"))

