    # -- request cost ----------------------------------------------------------

    def test_requests_at_once_share_one_read_of_the_index(self):
        """Every route used to rebuild its own copy after each index write:
        four at once, four whole-table reads."""
        self.load(self.fixture())
        self.index_library()
        self.summary()
        bot._index_mark_release_present(rgid="rg-3")          # the index head moves
        reads, real = [], bot._listens_read_held

        def slow():
            reads.append(1)
            time.sleep(0.05)
            return real()

        answers = []
        with patch.object(bot, "_listens_read_held", slow):
            threads = [threading.Thread(target=lambda: answers.append(self.summary()))
                       for _ in range(4)]
            for t in threads:
                t.start()
            for t in threads:
                t.join(10)
            self.assertEqual(len(reads), 1)
            self.summary()
            self.assertEqual(len(reads), 1, "and it is kept until the index moves again")
        self.assertEqual(len(answers), 4)
        self.assertTrue(all(a["topAlbums"][2]["owned"] for a in answers), "rg-3 is held now")

    def test_a_new_listen_drops_every_aggregate_of_the_listens_before_it(self):
        """They are keyed on the listens they were computed from, so none of
        them can be asked for again — and an all-time calendar with its album
        groups is tens of megabytes, kept until 24 newer entries pushed it out."""
        self.load(self.fixture())
        self.summary("7d")
        self.summary("all")
        bot._listening_unowned_view("30d", "artist", "30", now=self.now)
        before = bot._listens_stamp()
        with bot._listens_memo_lock:
            held = len(bot._listens_memo)
            self.assertEqual({key[-3:] for key in bot._listens_memo}, {before})
        self.assertGreaterEqual(held, 8)
        self.listens.append(self.listen(self.now - 5, "Newest", "Alpha", "First"))
        self.assertEqual(self.tick(bot._listens_new_state(), self.now + 86400.0 * 2), "synced")
        after = bot._listens_stamp()
        self.assertNotEqual(after, before)
        self.summary("7d")
        with bot._listens_memo_lock:
            self.assertEqual({key[-3:] for key in bot._listens_memo}, {after})
            self.assertLess(len(bot._listens_memo), held)

    def test_requests_at_once_share_one_aggregation(self):
        """Four proxy slots: four summaries asked for together used to run
        four scans of the history side by side."""
        self.load(self.fixture())
        calls, real = [], bot._listens_groups

        def slow(conn, kind, start_ts):
            calls.append(kind)
            time.sleep(0.05)
            return real(conn, kind, start_ts)

        answers = []
        with patch.object(bot, "_listens_groups", slow):
            threads = [threading.Thread(target=lambda: answers.append(self.summary()))
                       for _ in range(4)]
            for t in threads:
                t.start()
            for t in threads:
                t.join(10)
        self.assertEqual(sorted(calls), ["album", "artist", "track"])
        self.assertEqual(len(answers), 4)
        self.assertTrue(all(a == answers[0] for a in answers))

    def test_a_grouping_reads_its_period_and_reads_all_of_history_as_a_scan(self):
        """What SQLite's planner does with the grouping SQL, which is where a
        quarter of a second of every period's first request went: it walked
        the whole artist index in group order and filtered the period row by
        row. And all of history was every row fetched through the time index."""
        self.load(self.fixture())
        with bot._listens_reader() as conn:
            def plans(start_ts):
                seen = []
                conn.set_trace_callback(seen.append)
                for kind in ("artist", "album", "track"):
                    bot._listens_groups(conn, kind, start_ts)
                conn.set_trace_callback(None)
                self.assertEqual(len(seen), 3)
                return [" / ".join(r[3] for r in conn.execute("EXPLAIN QUERY PLAN " + sql))
                        for sql in seen]

            for plan in plans(1_000):
                self.assertIn("idx_listens_at (listened_at>?)", plan)
            for plan in plans(0):
                self.assertIn("SCAN listens", plan)
                self.assertNotIn("idx_listens", plan)

    def test_an_aggregation_does_not_hold_the_lock_status_needs(self):
        self.load(self.fixture())
        held = []
        real_groups, real_calendar = bot._listens_groups, bot._listens_calendar_scan

        def groups(*a, **k):
            held.append(bot._listens_lock.locked())
            return real_groups(*a, **k)

        def calendar(*a, **k):
            held.append(bot._listens_lock.locked())
            return real_calendar(*a, **k)

        with patch.object(bot, "_listens_groups", groups), \
                patch.object(bot, "_listens_calendar_scan", calendar):
            self.summary("all")
        self.assertEqual(held, [False, False, False, False])

