    def test_summary_hours_across_the_autumn_clock_change(self):
        """2026-10-25 in Berlin has 25 hours: 02:00–03:00 happens twice."""
        self.load([
            self.listen(self.at(2026, 10, 25, 0, 30, utc=True), "a"),    # 02:30 CEST
            self.listen(self.at(2026, 10, 25, 1, 30, utc=True), "b"),    # 02:30 CET
            self.listen(self.at(2026, 10, 25, 22, 59, utc=True), "c"),   # 23:59 CET, same day
            self.listen(self.at(2026, 10, 25, 23, 0, utc=True), "d")])   # 00:00 on the 26th
        s = self.summary("7d", now=self.at(2026, 10, 26, 12, 0))
        self.assertEqual({d["date"]: d["count"] for d in s["daily"] if d["count"]},
                         {"2026-10-25": 3, "2026-10-26": 1})
        self.assertEqual((s["hours"][2], s["hours"][23], s["hours"][0]), (2, 1, 1))
        self.assertEqual(s["totals"]["plays"], 4)
        # Seen at 00:30 on the 26th the period still begins on the 20th, a
        # 25-hour day inside it notwithstanding.
        s = self.summary("7d", now=self.at(2026, 10, 26, 0, 30))
        self.assertEqual((s["daily"][0]["date"], len(s["daily"])), ("2026-10-20", 7))

