    def test_recent_never_splits_one_second_across_two_pages(self):
        """`before` is exclusive, so a second cut by a page boundary would
        lose its other listens: the page stops before that second instead."""
        self.load([self.listen(400, "d"), self.listen(300, "c2"), self.listen(300, "c1"),
                   self.listen(200, "b"), self.listen(100, "a")])
        page, _ = bot._listening_recent_view("", "2", now=1000)
        self.assertEqual(([r["track"] for r in page["rows"]], page["nextBefore"]), (["d"], 400))
        page, _ = bot._listening_recent_view("400", "2", now=1000)
        self.assertEqual(sorted(r["track"] for r in page["rows"]), ["c1", "c2"])
        page, _ = bot._listening_recent_view(str(page["nextBefore"]), "2", now=1000)
