    # ── A cancel that lands while a placement is running ────────────────────

    def _cancel_mid_import(self, cancel, at="mbz_release_tracks"):
        """Have `cancel` run to its end, on a thread of its own, while an
        import is under way: at the tracklist lookup, which every import makes
        before it moves a file — or `at` another step of the placement.
        Returns (patch, [what the cancel answered])."""
        real, answered, fired = getattr(bot, at), [], []

        def step(*a, **k):
            if not fired:
                fired.append(True)
                th = threading.Thread(target=lambda: answered.append(cancel()))
                th.start()
                th.join(5)
                self.assertFalse(th.is_alive(), "the cancel waited on the placement")
            return real(*a, **k)

        return patch.object(bot, at, step), answered

    def _fetch_all_three(self, client, asked):
        self._sources(("first", "Record", list(self.ALBUM_FILES)))
        for name in self.ALBUM_FILES:
            self._file(self.album_dir, name)
        r = client.post("/api/gaps/g1/fetch", json={"sourceId": 0})
        self.assertEqual(r.status_code, 200, r.get_json())

    def _assert_all_three_are_in_the_library_and_say_so(self, client, asked):
        self.assertEqual(self._placed_files(), list(self.ALBUM_FILES))
        self.assertEqual({t: self._row(t)["decision"] for t in ("Two", "Three", "Four")},
                         {"Two": "placed", "Three": "placed", "Four": "placed"})
        self.assertEqual(self.verified, ["g1"])
        self.assertEqual(bot._album_fill_get(self.RELEASE).get("state"), "placed")
        # And nothing asks for them again.
        del asked[:]
        r = client.post("/api/gaps/g1/fetch", json={"sourceId": 0})
        self.assertEqual((r.status_code, r.get_json().get("code")), (400, "nothing_to_fetch"))
        self.assertEqual(asked, [])

    def test_a_gap_cancel_during_a_finalizes_import_does_not_unplace_its_rows(self):
        """The finalize has taken its album group out of the table and is
        moving the files. A gap cancel finds no group — and used to settle the
        landed rows `cancelled` all the same: the finalize then skipped them,
        so the files were in the library under rows that read cancelled, with
        no verifier, for the next fetch to download again."""
        client = _web_app().test_client()
        asked = []
        with self._slskd(), self._asking(asked):
            self._fetch_all_three(client, asked)
            hook, answered = self._cancel_mid_import(
                lambda: client.post("/api/gaps/g1/cancel").get_json()["cancelled"])
            with hook:
                self._poll(*(("first", name) for name in self.ALBUM_FILES))
            # Nothing was still transferring; too late for the rest.
            self.assertEqual(answered, [0])
            self._assert_all_three_are_in_the_library_and_say_so(client, asked)

    def test_an_album_cancel_during_a_finalizes_import_is_too_late_as_before(self):
        client = _web_app().test_client()
        asked = []
        with self._slskd(), self._asking(asked):
            self._fetch_all_three(client, asked)
            hook, answered = self._cancel_mid_import(
                lambda: client.post("/api/album/cancel",
                                    json={"release_mbid": self.RELEASE}).get_json())
            with hook:
                self._poll(*(("first", name) for name in self.ALBUM_FILES))
            self.assertEqual((answered[0]["cancelled"], answered[0]["status"]["state"]),
                             (False, "placing"))
            self._assert_all_three_are_in_the_library_and_say_so(client, asked)

