        hook, answered = self._cancel_mid_import(
            lambda: bot._cancel_album_fill(self.RELEASE, bot.USER_CANCEL_REASON))
        with patch.object(bot, "_abandon_transfers_async", lambda entries: None), hook:
            self._poll(("first", "03 - Three.flac"))
