    def test_place_anyway_waits_its_turn_without_the_review_lock(self):
        """It imports under the review lock, so it claims before taking it:
        waiting for the claim with the lock held would deadlock against the
        placement that holds the claim and needs the lock to write its rows."""
        self._refuse_as_duplicate()
        self._transfer("Two", "peer", self.other_dir, "b-side.flac",
                       manual_pick={"username": "peer", "filename": "Music\\b-side.flac"})
        self._poll(("peer", "b-side.flac"))
        self.assertTrue(self._row("Two")["can_force_place"])
        waiting = threading.Event()

        class Watched(threading.Condition):
            def wait(self, timeout=None):
                waiting.set()
                return super().wait(timeout)

        client, answered = _web_app().test_client(), []
        with patch.object(bot, "_placing_cond", Watched()):
            with bot._group_placement("g1"):
                route = threading.Thread(target=lambda: answered.append(
                    client.post("/api/groups/g1/tracks/0/place-anyway").status_code))
                route.start()
                self.assertTrue(waiting.wait(5), "Place anyway did not wait for the claim")
                self.assertEqual(answered, [])
                # The placement that holds the claim can still write its rows.
                free = bot._review_lock.acquire(timeout=2)
                self.assertTrue(free, "Place anyway waits with the review lock held")
                bot._review_lock.release()
            route.join(5)
        self.assertEqual(answered, [200])
        self.assertEqual(self._row("Two")["decision"], "placed")
        self.assertFalse(bot._group_placement_active("g1"))

