def _mb_release(media, release_id="rel", title="Album") -> dict:
    """A MusicBrainz release document (`inc=recordings`) from rows shaped like
    LONERISM_MEDIA."""
    return {"id": release_id, "title": title, "media": [
        {"position": position, "format": fmt, "track-count": len(tracks),
         "tracks": [{"id": track_id, "position": n, "number": str(n), "title": name,
                     "length": ms,
                     "recording": {"id": recording, "title": name, "length": ms}}
                    for n, (track_id, recording, name, ms) in enumerate(tracks, 1)]}
        for position, fmt, tracks in media]}


def _medium(position, *titles, prefix=None, recordings=None):
    """One medium for `_mb_release`: titles in order, ids made from them."""
    prefix = prefix or f"d{position}"
    return (position, "CD", tuple(
        (f"{prefix}-t{n}", (recordings or {}).get(title, f"rec-{title}"), title, 200000 + n)
        for n, title in enumerate(titles, 1)))


class MultiMediumReleaseTests(unittest.TestCase):
    """A release is its media, and two of them can be one album twice.

    Lonerism's box (release d105e2cd) is the album on two LPs, the album again
    on a CD, and a 7" single. Read flat it was 26 tracks with positions 1–6,
    1–6, 1–12, 1–2 and no disc on any of them: eight files were placed as
    disc 1 tracks 1,2,2,3,4,4,5,6 beside older ones, and every title counted
    twice (present 24/26).
    """

    def rows(self, *media):
        return bot._release_tracks_from(_mb_release(media))

    def test_the_lonerism_box_is_fourteen_rows_on_discs_three_and_four(self):
        rows = bot._release_tracks_from(_mb_release(LONERISM_MEDIA, LONERISM, "Lonerism"))
        self.assertEqual([(r["disc"], r["position"]) for r in rows],
                         [(3, n) for n in range(1, 13)] + [(4, 1), (4, 2)])
        # MusicBrainz's own numbers: disc 3 of 4, never renumbered to 1 of 2.
        self.assertEqual({r["disc_total"] for r in rows}, {4})
        self.assertEqual([r["disc_tracks"] for r in rows], [12] * 12 + [2, 2])
        elephant = rows[8]
        self.assertEqual((elephant["title"], elephant["mbid"], elephant["track_id"],
                          elephant["duration"]),
                         ("Elephant", "920be16d-e040-433d-b941-39bef05543b0",
                          "882d62ba-0e76-40b8-939a-66c2733683d8", 211.0))
        self.assertEqual([r["title"] for r in rows[12:]], ["Led Zeppelin", "Beverly Laurel"])

    def test_an_ordinary_two_disc_release_keeps_both_discs(self):
        rows = self.rows(_medium(1, "A", "B"), _medium(2, "C", "D", "E"))
        self.assertEqual([(r["disc"], r["position"], r["title"]) for r in rows],
                         [(1, 1, "A"), (1, 2, "B"), (2, 1, "C"), (2, 2, "D"), (2, 3, "E")])
        self.assertEqual([(r["disc_total"], r["disc_tracks"]) for r in rows],
                         [(2, 2), (2, 2), (2, 3), (2, 3), (2, 3)])

    def test_an_identical_second_disc_keeps_the_first(self):
        rows = self.rows(_medium(1, "A", "B"), _medium(2, "A", "B"))
        self.assertEqual([(r["disc"], r["track_id"]) for r in rows],
                         [(1, "d1-t1"), (1, "d1-t2")])
        self.assertEqual({r["disc_total"] for r in rows}, {2})

    def test_a_medium_is_dropped_only_for_one_other_that_holds_all_of_it(self):
        # The CD is not dropped for being spread over the two LPs, and a disc
        # that shares a song with another is not that disc again.
        rows = self.rows(_medium(1, "A", "B"), _medium(2, "C", "D"),
                         _medium(3, "A", "B", "C", "D"), _medium(4, "A", "Z"))
        self.assertEqual([r["disc"] for r in rows], [3, 3, 3, 3, 4, 4])

    def test_a_track_with_no_recording_id_is_never_a_repeat(self):
        # Two tracks MusicBrainz has no recording for are not known to be one.
        rows = self.rows(_medium(1, "A", "B", recordings={"B": ""}),
                         _medium(2, "A", "B", "C", recordings={"B": ""}))
        self.assertEqual([r["disc"] for r in rows], [1, 1, 2, 2, 2])

    def test_a_release_with_no_medium_numbers_counts_them(self):
        doc = _mb_release((_medium(1, "A"), _medium(2, "B")))
        for medium in doc["media"]:
            del medium["position"]
        self.assertEqual([(r["disc"], r["disc_total"]) for r in bot._release_tracks_from(doc)],
                         [(1, 2), (2, 2)])

    # ── what is present, and what is missing ────────────────────────────────

    def _missing(self, songs):
        doc = _mb_release(LONERISM_MEDIA, LONERISM, "Lonerism")
        with patch.object(bot, "mbz_release_tracks", lambda mbid: bot._release_tracks_from(doc)):
            return bot._missing_for_album_records(
                [{"id": "a1", "tracks": songs}], LONERISM, "Tame Impala")

    def test_the_album_in_the_library_leaves_the_two_b_sides_missing(self):
        album = [name for _t, _r, name, _ms in LONERISM_MEDIA[2][2]]
        result = self._missing([{"title": name, "path": f"/music/{n}.flac"}
                                for n, name in enumerate(album, 1)])
        self.assertEqual((result["present"], result["total"]), (12, 14))
        self.assertEqual([(t["title"], t["disc"], t["position"], t["disc_total"])
                          for t in result["missing"]],
                         [("Led Zeppelin", 4, 1, 4), ("Beverly Laurel", 4, 2, 4)])

    def test_a_song_tagged_on_a_dropped_medium_is_still_present(self):
        # Present means the recording, else the title — never the medium. A
        # file filed as the LP side C3 is the song, whatever disc it says.
        songs = [{"title": f"side {n}", "musicBrainzId": recording,
                  "discNumber": position, "track": n, "path": f"/music/{position}-{n}.flac"}
                 for position, _fmt, tracks in LONERISM_MEDIA[:2]
                 for n, (_track, recording, _name, _ms) in enumerate(tracks, 1)]
        result = self._missing(songs)
        self.assertEqual((result["present"], result["total"]), (12, 14))
        self.assertEqual([t["title"] for t in result["missing"]],
                         ["Led Zeppelin", "Beverly Laurel"])

    def test_a_gaps_rows_say_which_disc_they_are_on(self):
        # On the wire, beside `position` — which alone reads 1, 2 after the
        # album's own 1–12. A row with no disc on record says 0, "not known":
        # one scanned before discs were kept, and the songs the library has
        # (Navidrome's album record carries none).
        missing = self._missing([{"title": name, "path": f"/music/{n}.flac"}
                                 for n, (_t, _r, name, _ms) in enumerate(LONERISM_MEDIA[2][2], 1)])
        group = {"id": "g1", "artist": "Tame Impala", "album": "Lonerism",
                 "canonical_album_id": "a1",
                 "albums": [{"id": "a1", "tracks": [{"title": "Be Above It"}]}],
                 "missing_tracks": missing["missing"] + [
                     {"title": "A row from before", "mbid": "old", "position": 3,
                      "decision": "pending"}]}
        rows = [(t["title"], t["disc"], t["position"])
                for t in bot._gap_detail_view(group)["tracks"]]
        self.assertEqual(rows, [("Be Above It", 0, 1), ("Led Zeppelin", 4, 1),
                                ("Beverly Laurel", 4, 2), ("A row from before", 0, 3)])
        # The rows the view is built from carry it too.
        self.assertEqual([r["disc"] for r in bot._canonical_tracklist_from_group(group)],
                         [0, 4, 4, 0])

    # ── every "the position is the track" assumption ────────────────────────

    def test_missing_rows_sort_by_disc_then_position(self):
        rows = [{"title": "c", "disc": 2, "position": 1}, {"title": "b", "disc": 1, "position": 5},
                {"title": "a", "position": 9}]
        self.assertEqual([t["title"] for t in sorted(rows, key=bot._missing_track_sort_key)],
                         ["a", "b", "c"])

    def test_a_file_names_its_disc_in_the_ways_peers_write_it(self):
        for name, want in (("05 - Song.flac", (0, 5)),
                           ("1-05 - Song.flac", (1, 5)),
                           ("2.01 Song.flac", (2, 1)),
                           ("Album\\CD2\\05 - Song.flac", (2, 5)),
                           ("Album/Disc 1/03.flac", (1, 3)),
                           ("Tame Impala - Currents - 07 - The Less I Know.flac", (0, 7)),
                           ("105 - Song.flac", (0, 105)),
                           ("1-800 Number.flac", (0, 1)),
                           ("Song.flac", (0, 0))):
            with self.subTest(name=name):
                self.assertEqual(bot._filename_disc_track(name), want)
                self.assertEqual(bot._filename_track_number(name), want[1])

    def test_durations_are_stamped_by_disc_and_position(self):
        doc = _mb_release((_medium(1, "A", "B"), _medium(2, "C", "D")))
        group = {"canonical_mbid": "rel", "missing_tracks": [
            {"title": "ツー", "disc": 2, "position": 2},     # no recording id to go by
            {"title": "old row", "position": 1}]}           # scanned before discs: no telling
        with patch.object(bot, "_release_tracks_cached",
                          lambda mbid: bot._release_tracks_from(doc)):
            self.assertEqual(bot._stamp_missing_durations(group), 1)
        self.assertEqual(group["missing_tracks"][0]["duration"], 200.002)
        self.assertNotIn("duration", group["missing_tracks"][1])

    def test_the_releases_rows_tell_two_discs_first_tracks_apart(self):
        group = {"albums": [], "missing_tracks": [
            {"title": "Intro", "disc": 1, "position": 1, "duration": 60},
            {"title": "Intro", "disc": 2, "position": 1, "duration": 90}]}
        rows = bot._release_rows(group)
        self.assertEqual([(r["title"], r["disc"], r["position"], r["duration"]) for r in rows],
                         [("Intro", 1, 1, 60), ("Intro", 2, 1, 90)])
        # …and the row being paired is not added again, while its namesake
        # on the other disc is still a sibling.
        first = group["missing_tracks"][0]
        both = bot._with_release_rows([first], rows)
        self.assertIs(both[0], first)
        self.assertEqual([(r["disc"], r["position"]) for r in both], [(1, 1), (2, 1)])

    # ── the exact-count zip ─────────────────────────────────────────────────

    def _zip(self, names, rows):
        files = [{"filename": f"Peer\\Album\\{name}", "size": 1} for name in names]
        return [(f["filename"].rsplit("\\", 1)[-1], t["title"])
                for f, t in bot._exact_count_zip(files, rows)]

    def test_two_rows_at_one_position_are_never_zipped(self):
        # Rows scanned before discs were kept: both read position 1, and two
        # files numbered 01 used to pair with them in filename order.
        rows = [{"title": "一", "position": 1}, {"title": "二", "position": 1}]
        self.assertEqual(self._zip(["01 - a.flac", "01 - b.flac"], rows), [])
        # Files that can be told apart do not tell the rows apart.
        self.assertEqual(self._zip(["01 - a.flac", "1-01 - b.flac"], rows), [])

    def test_two_files_with_one_number_are_never_zipped(self):
        # Rows that say which disc they are on but not how many there are, so
        # a bare number is not refused for naming no disc: each "01" does name
        # a first track. Which one is which, only the file order would say.
        rows = [{"title": "一", "disc": 1, "position": 1},
                {"title": "二", "disc": 2, "position": 1}]
        self.assertEqual(self._zip(["01 - a.flac", "01 - b.flac"], rows), [])
        # Told apart, the same rows do zip.
        self.assertEqual(self._zip(["1-01 - a.flac", "2-01 - b.flac"], rows),
                         [("1-01 - a.flac", "一"), ("2-01 - b.flac", "二")])

    def test_on_several_discs_a_bare_number_names_no_row(self):
        rows = [{"title": "三", "disc": 2, "disc_total": 2, "position": 3},
                {"title": "四", "disc": 2, "disc_total": 2, "position": 4}]
        # Tracks 3 and 4 of which disc? The library has disc 1's.
        self.assertEqual(self._zip(["03 - a.flac", "04 - b.flac"], rows), [])
        self.assertEqual(self._zip(["1-03 - a.flac", "1-04 - b.flac"], rows), [])
        self.assertEqual(self._zip(["2-03 - a.flac", "2-04 - b.flac"], rows),
                         [("2-03 - a.flac", "三"), ("2-04 - b.flac", "四")])

    def test_gaps_on_two_discs_zip_with_files_that_name_both(self):
        rows = [{"title": "二", "disc": 2, "disc_total": 2, "position": 1},
                {"title": "一", "disc": 1, "disc_total": 2, "position": 1}]
        self.assertEqual(self._zip(["2-01 - b.flac", "1-01 - a.flac"], rows),
                         [("1-01 - a.flac", "一"), ("2-01 - b.flac", "二")])
        # The disc in the folder's name, and file names that sort the other way.
        self.assertEqual(self._zip(["CD2\\01 - a.flac", "CD1\\01 - z.flac"], rows),
                         [("01 - z.flac", "一"), ("01 - a.flac", "二")])

    def test_a_single_disc_release_still_zips_on_bare_numbers(self):
        rows = [{"title": "五", "disc": 1, "disc_total": 1, "position": 5},
                {"title": "六", "disc": 1, "disc_total": 1, "position": 6}]
        self.assertEqual(self._zip(["05 - a.flac", "06 - b.flac"], rows),
                         [("05 - a.flac", "五"), ("06 - b.flac", "六")])
        # A file that names the disc must name this one.
        self.assertEqual(self._zip(["1-05 - a.flac", "1-06 - b.flac"], rows),
                         [("1-05 - a.flac", "五"), ("1-06 - b.flac", "六")])
        self.assertEqual(self._zip(["2-05 - a.flac", "2-06 - b.flac"], rows), [])

    # ── the whole-album track-number tier ───────────────────────────────────

    def _whole_album(self, names):
        """A two-disc release of two tracks each; the library has all but the
        first track of disc 2, whose title no peer writes the same way."""
        present = [{"title": title, "disc": disc, "position": pos}
                   for title, disc, pos in (("Alpha", 1, 1), ("Beta", 1, 2), ("Delta", 2, 2))]
        gap = {"title": "ガンマ", "disc": 2, "disc_total": 2, "position": 1}
        files = [{"filename": f"Peer\\Album\\{name}", "size": 1} for name in names]
        bases = {}
        pairs = bot._album_file_pairs_for_missing_tracks(
            files, [gap], siblings=["Alpha", "Beta", "Delta"],
            folder={"album_match_ok": True}, release_total=4,
            release_tracks=[gap] + present, bases=bases, blind_zip=False, log=False)
        return [f["filename"].rsplit("\\", 1)[-1] for f, _t in pairs], set(bases.values())

    def test_the_track_number_tier_reads_the_disc(self):
        self.assertEqual(
            self._whole_album(["1-01 - Alpha.flac", "1-02 - Beta.flac",
                               "2-01 - Gamma.flac", "2-02 - Delta.flac"]),
            (["2-01 - Gamma.flac"], {"position"}))

    def test_the_track_number_tier_takes_nothing_for_two_rows_at_one_place(self):
        # Gaps scanned before discs were kept, on a two-disc release: both
        # read position 1, and one file numbered 01 cannot be both.
        gaps = [{"title": "一", "position": 1}, {"title": "二", "position": 1}]
        files = [{"filename": f"Peer\\Album\\{name}", "size": 1}
                 for name in ("01 - Unreadable.flac", "02 - Beta.flac",
                              "03 - Other.flac", "04 - Delta.flac")]
        pairs = bot._album_file_pairs_for_missing_tracks(
            files, gaps, siblings=["Beta", "Delta"], folder={"album_match_ok": True},
            release_total=4, release_tracks=gaps + [{"title": "Beta"}, {"title": "Delta"}],
            blind_zip=False, log=False)
        self.assertEqual(pairs, [])

    def test_the_track_number_tier_takes_no_bare_number_on_several_discs(self):
        # "01" here is disc 1's first track under a name nobody recognises:
        # it used to be fetched for disc 2's.
        self.assertEqual(
            self._whole_album(["01 - Unreadable.flac", "02 - Beta.flac",
                               "03 - Gamma.flac", "04 - Delta.flac"]),
            ([], set()))


class _PlacedOnDisk:
    """Real FLAC files through the real import and the real tag writer, into a
    library in a temp folder. MusicBrainz and Navidrome are the fakes;
    `self.release` is the release document every lookup answers with."""

    def setUp(self):
        import shutil
        tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, tmp, True)
        self.downloads = os.path.join(tmp, "downloads", "Peer Folder")
        self.lib = os.path.join(tmp, "music")
        os.makedirs(self.lib)
        self.release = _mb_release(LONERISM_MEDIA, LONERISM, "Lonerism")
        for name, value in (
                ("MUSIC_LIBRARY_PATH", self.lib),
                ("_default_web_user", lambda *a, **k: {}),
                ("mbz_release_tracks", lambda mbid: bot._release_tracks_from(self.release)),
                ("mbz_release_display", lambda *a, **k: {"release_date": "2012-10-05"}),
                ("rgid_from_release", lambda *a, **k: "rg-1")):
            patcher = patch.object(bot, name, value)
            patcher.start()
            self.addCleanup(patcher.stop)

    def place(self, artist="Tame Impala", album="Lonerism"):
        result = bot._deterministic_album_import(self.downloads, "rel-1", artist, album)
        self.assertTrue(result["ok"], result)
        return result

    def placed(self, artist="Tame Impala", album="Lonerism"):
        folder = os.path.join(self.lib, artist, album)
        return {name: _flac_tags(os.path.join(folder, name)) for name in sorted(os.listdir(folder))}


class PlacementNumbersFromTheSlotTests(_PlacedOnDisk, unittest.TestCase):
    """Placement numbers a file by the slot it fills, on real files.

    `_place` wrote `track` from the slot and everything else about the
    numbering from the downloaded file or from the flat tracklist: the disc
    was the file's own or 1, the track total every medium's tracks together.
    """

    def test_a_file_is_numbered_by_its_slot_not_by_its_own_tags(self):
        # A peer's rip of the LP: side C, track 3 of 6, disc 2.
        _tiny_flac(os.path.join(self.downloads, "C3 - Elephant.flac"),
                   tags={"title": "Elephant", "tracknumber": "3", "tracktotal": "6",
                         "discnumber": "2", "disctotal": "2"})
        _tiny_flac(os.path.join(self.downloads, "Led Zeppelin.flac"),
                   tags={"title": "Led Zeppelin"})
        self.place()
        placed = self.placed()
        self.assertEqual(sorted(placed), ["3-09 - Elephant.flac", "4-01 - Led Zeppelin.flac"])
        numbers = {name: {key: tags[key] for key in
                          ("tracknumber", "tracktotal", "discnumber", "disctotal")}
                   for name, tags in placed.items()}
        self.assertEqual(numbers, {
            "3-09 - Elephant.flac": {"tracknumber": ["9"], "tracktotal": ["12"],
                                     "discnumber": ["3"], "disctotal": ["4"]},
            "4-01 - Led Zeppelin.flac": {"tracknumber": ["1"], "tracktotal": ["2"],
                                         "discnumber": ["4"], "disctotal": ["4"]}})

    def test_a_single_medium_release_keeps_its_plain_file_names(self):
        self.release = _mb_release((_medium(1, "One", "Two", "Three"),), "rel-1", "Album")
        _tiny_flac(os.path.join(self.downloads, "Two.flac"),
                   tags={"title": "Two", "tracknumber": "7", "discnumber": "3"})
        self.place("Band", "Album")
        placed = self.placed("Band", "Album")
        self.assertEqual(list(placed), ["02 - Two.flac"])
        self.assertEqual({key: placed["02 - Two.flac"][key] for key in
                          ("tracknumber", "tracktotal", "discnumber", "disctotal")},
                         {"tracknumber": ["2"], "tracktotal": ["3"],
                          "discnumber": ["1"], "disctotal": ["1"]})

    def test_a_box_that_keeps_one_medium_names_its_files_plainly(self):
        # Two LPs and the CD they repeat: one medium is left, so nothing needs
        # telling apart by disc in a file name — but the disc is still the
        # one MusicBrainz numbers it.
        self.release = _mb_release((_medium(1, "A", "B"), _medium(2, "C", "D"),
                                    _medium(3, "A", "B", "C", "D")), "rel-1", "Album")
        _tiny_flac(os.path.join(self.downloads, "C.flac"), tags={"title": "C"})
        self.place("Band", "Album")
        placed = self.placed("Band", "Album")
        self.assertEqual(list(placed), ["03 - C.flac"])
        self.assertEqual({key: placed["03 - C.flac"][key] for key in
                          ("tracknumber", "tracktotal", "discnumber", "disctotal")},
                         {"tracknumber": ["3"], "tracktotal": ["4"],
                          "discnumber": ["3"], "disctotal": ["3"]})

    def test_an_extra_track_keeps_its_own_numbers(self):
        # No slot, so nothing to number it by: it is filed as the file itself
        # says, and is given no track total that is not its own.
        # (Two of the album's three tracks beside it: a file with no slot is
        # an extra track only of an album the folder has shown itself to be.)
        self.release = _mb_release((_medium(1, "One", "Two", "Three"),), "rel-1", "Album")
        _tiny_flac(os.path.join(self.downloads, "One.flac"), tags={"title": "One"})
        _tiny_flac(os.path.join(self.downloads, "Two.flac"), tags={"title": "Two"})
        _tiny_flac(os.path.join(self.downloads, "Hidden.flac"),
                   tags={"title": "Hidden Song", "tracknumber": "9", "tracktotal": "9",
                         "discnumber": "2", "album": "Album"})
        self.place("Band", "Album")
        placed = self.placed("Band", "Album")
        self.assertEqual(sorted(placed), ["01 - One.flac", "02 - Two.flac",
                                          "09 - Hidden Song.flac"])
        extra = placed["09 - Hidden Song.flac"]
        self.assertEqual((extra["tracknumber"], extra["tracktotal"], extra["discnumber"]),
                         (["9"], ["9"], ["2"]))

    def test_the_outcome_names_the_disc_of_the_slot(self):
        _tiny_flac(os.path.join(self.downloads, "Beverly Laurel.flac"),
                   tags={"title": "Beverly Laurel"})
        result = self.place()
        row = next(r for r in result["per_file"] if r.get("status") == "matched")
        self.assertEqual((row["disc"], row["position"], row["title"]),
                         (4, 2, "Beverly Laurel"))



class ArtistFoldTests(unittest.TestCase):
    """`_artist_fold`: two spellings of one name fold alike, and nothing else."""

    def test_spellings_of_one_name_fold_alike(self):
        for a, b in (("Belle & Sebastian", "Belle and Sebastian"),
                     ("Belle & Sebastian", "belle + sebastian"),
                     ("Belle and Sebastian", "Belle  And  Sebastian!"),
                     ("AC/DC", "ACDC"),
                     ("Sigur Rós", "sigur rós"),
                     ("Кино!", "кино"),                           # in any script
                     ("Beyoncé", "Beyoncé"),          # decomposed and composed
                     ("Ｋｉｎｏ", "Kino")):                      # full-width letters
            with self.subTest(a=a, b=b):
                self.assertEqual(bot._artist_fold(a), bot._artist_fold(b))

    def test_different_names_stay_different(self):
        for a, b in (("Belle & Sebastian", "Belle"),
                     ("Belle and Sebastian", "Belle and Sebastian feat. Monica Queen"),
                     ("Björk", "Bjork"),                           # an accent is a letter
                     ("Кино", "Алиса"),
                     ("DJ Кино", "DJ Алиса"),
                     ("坂本龍一", "坂本慎太郎"),
                     ("की", "का"),                                # a vowel sign is not punctuation
                     ("!!!", "???")):
            with self.subTest(a=a, b=b):
                self.assertNotEqual(bot._artist_fold(a), bot._artist_fold(b))

    def test_a_name_never_folds_to_nothing(self):
        # `_norm_album_text` answers "" for every one of these (B-060).
        for name in ("Кино", "坂本龍一", "שלום חנוך", "!!!", "+/-"):
            with self.subTest(name=name):
                self.assertTrue(bot._artist_fold(name))


