# The two releases of the 2026-10-10 incident, and the two folders that were
# filed as them. (title, seconds) — the lengths are the real ones.
AFTER_EP = "af0ee34d-fd5b-485c-9861-de0a091dfd82"
AFTER_EP_TRACKS = (("300 dreams", 188.6), ("Ever", 180.7), ("Lichen", 181.4),
                   ("Obvious", 209.7), ("Nothingmore", 216.1))
AFTER_EP_2 = "a65d7f2a-7c61-4a7c-a48b-683c685756df"
