        self.assertEqual(self.in_library(), ["01 - Deep Diving.flac"])
        self.assertEqual(self.in_downloads(), ["Unbekannt.flac"])
        # …and a folder with no track of the release in it is still refused.
        self.start_over()
        self.download(OVERWERK_AFTER_HOURS, artist="OVERWERK", album="After Hours EP")
        result = self.imported()
        self.assertEqual((result["ok"], result["moved"]), (False, 0), result)
        self.assertIn("none of", result["error"].lower())

