    def gap_group(self, positions, **more):
        review = isolated_review()
        review.__enter__()
        self.addCleanup(review.__exit__, None, None, None)
        with bot._review_lock:
            bot._review_state["groups"] = [{
                "id": "g1", "group_type": "incomplete", "origin": "library",
                "artist": "After", "album": "After EP 2", "canonical_mbid": AFTER_EP_2,
                "canonical_album_id": "al-1", "albums": [{"id": "al-1"}], "total": 6,
                "missing_tracks": [
                    {"title": title, "mbid": f"rec-{title}", "recording_mbid": f"rec-{title}",
                     "position": n, "disc": 1, "decision": "downloaded"}
                    for n, (title, _s) in enumerate(AFTER_EP_2_TRACKS, 1) if n in positions],
                **more}]

    def test_a_gap_fill_places_the_one_row_that_landed(self):
        # Three rows wanted, one file arrived: a review group says which
        # tracks are wanted, and each one found is placed, as before.
        self.gap_group((4, 5, 6))
        self.download(AFTER_EP_2_TRACKS[4:5], numbered=False)
        with bot._group_placement("g1"):
            result = self.imported(group_id="g1", unattended=True)
        self.assertEqual((result["ok"], result["moved"]), (True, 1), result)
        self.assertEqual(self.in_library(), ["05 - Outbound.flac"])
        # A group id that names no group is no group.
        self.start_over()
        self.download(AFTER_EP_2_TRACKS[4:5], numbered=False)
        with bot._group_placement("gone"):
            result = self.imported(group_id="gone", unattended=True)
        self.assertEqual((result["ok"], result["moved"]), (False, 0), result)

    def hidden_track(self, number=7) -> str:
        """A bonus track of the album, numbered past its six tracks. (Numbered
        for a track that is still missing it would not be filed as an extra:
        ruling F2.)"""
        return _tiny_flac(
            os.path.join(self.downloads, f"{number:02d} - Hidden Track.flac"), seconds=90,
            tags={"title": "Hidden Track", "artist": "After", "albumartist": "After",
                  "album": "After EP 2", "tracknumber": str(number)})

