    # ── lengths alone need three (ruling C3, the review's I-2 and I-7) ──────

    FOREIGN = (("Alpha", 301), ("Beta", 250), ("Gamma", 212), ("Delta", 100),
               ("Epsilon", 500), ("Zeta", 180), ("Eta", 120))

    def test_one_or_two_lengths_do_not_show_a_short_release(self):
        # A length was "half of the slots" for a single, a two-track single
        # and — two of them — a four-track EP: the whole foreign folder was
        # filed, retagged as the release. No AcoustID opinion needed.
        # (Three tracks with two coincidences are "more than half" and not
        # three; six with three are three and not more than half.) The
        # coincidences sit where a length can be evidence at all (D1): each
        # at the number of the track it is as long as.
        for name, tracks in (
                ("a single", (("Obvious", 301.4),)),
                ("two tracks", (("One Song", 301.4), ("Other Song", 250.0))),
                ("three tracks", (("Aa", 301.0), ("Bb", 250.0), ("Cc", 420.0))),
                ("four tracks", (("Aa", 301.0), ("Bb", 250.0), ("Cc", 300.0), ("Dd", 420.0))),
                ("six tracks", (("Aa", 301.0), ("Bb", 250.0), ("Cc", 212.5), ("Dd", 420.0),
                                ("Ee", 600.0), ("Ff", 700.0)))):
            with self.subTest(release=name):
                self.release = _release_of("rel-short", "Short", tracks)
                self.start_over()
                self.download(self.FOREIGN, artist="Other Artist", album="Other Album")
                before = self.in_downloads()
                result = self.imported("rel-short", "After", "Short")
                self.assertEqual((result["ok"], result["moved"]), (False, 0), result)
                self.assertEqual(self.in_library(), [])
                self.assertEqual(self.in_downloads(), before)
                self.assertIn("After – Short", result["error"])

