    def test_what_was_not_taken_for_a_track_is_not_filed_as_an_extra_of_it(self):
        # (F2.) An untitled alternate take numbered 03 beside the titled
        # track 3 contradicts the numbering, so neither untitled file is
        # taken by its length — and both, carrying the album's tag, were
        # filed as extras under their own names: `11 - Lied 11.flac` in the
        # album folder while track 11 still read missing, to be fetched again.
        self.twelve_titled_and_untitled(("03 - take two.flac", 160, {"title": "take two"}))
        result = self.imported("rel-12", "Band", "Twelve", unattended=True)
        rows = {row["file"]: row for row in result["per_file"]}
        self.assertEqual((result["ok"], result["moved"]), (True, 11), result)
        # The two that may be tracks 11 and 12 stay where they are, saying so.
        self.assertEqual(self.in_downloads(), ["11 - Lied 11.flac", "12 - Lied 12.flac"])
        for n, title in ((11, "Song KK"), (12, "Song LL")):
            row = rows[f"{n:02d} - Lied {n}.flac"]
            self.assertEqual(row["status"], "rejected", row)
            self.assertIn(f"it may be track {n} (“{title}”)", row["reason"])
            self.assertIn("was not taken for it", row["reason"])
            self.assertNotIn("recording_mbid", row)
        self.assertEqual(_flac_tags(os.path.join(self.downloads, "11 - Lied 11.flac"))["title"],
                         ["Lied 11"])
        # The take numbered for a slot a titled file filled is an extra, as before.
        self.assertEqual(rows["03 - take two.flac"]["status"], "bonus")
        self.assertIn("take two.flac", self.in_library())
        self.assertEqual(len(self.in_library()), 11)

