    def test_a_length_pairs_only_with_the_slot_the_files_number_names(self):
        def slot(position, seconds, disc=1, discs=1):
            return {"title": f"t{disc}.{position}", "position": position, "duration": seconds,
                    "disc": disc, "disc_total": discs}

        def pair(slots, files, release=None, filled=()):
            """(the pairings, whether the files contradict their numbering)."""
            files = [{"name": f"f{n}", "number": number, "disc": disc, "length": seconds}
                     for n, (number, disc, seconds) in enumerate(files)]
            pairs, against = bot._pair_by_length(slots, files, release or slots, filled)
            return [(s["title"], f["name"]) for s, f in pairs], bool(against)

        ep = [slot(n, seconds) for n, seconds in
              enumerate((202.1, 208.4, 198.9, 205.6, 227.3, 196.7), 1)]
        # By its number, and within three whole seconds of that slot's length.
        self.assertEqual(pair(ep, [(1, 0, 202.0), (2, 0, 211.0), (3, 0, 196.0)]),
                         ([("t1.1", "f0"), ("t1.2", "f1"), ("t1.3", "f2")], False))
        # "Whole seconds" is each length rounded: under three seconds apart
        # always pairs, four and more never — and between the two it depends
        # on where the lengths round (3.98 s apart here, then 3.02 s).
        self.assertEqual(pair([slot(1, 198.51)], [(1, 0, 202.49)]), ([("t1.1", "f0")], False))
        self.assertEqual(pair([slot(1, 198.49)], [(1, 0, 201.51)]), ([], True))
        self.assertEqual(pair([slot(1, 198.6)], [(1, 0, 201.59)]), ([("t1.1", "f0")], False))
        self.assertEqual(pair([slot(1, 198.0)], [(1, 0, 202.0)]), ([], True))
        # A neighbour's length is no reason to refuse a file its own slot.
        self.assertEqual(pair(ep, [(6, 0, 198.9)]), ([("t1.6", "f0")], False))
        # **A numbered file that is not its slot's contradicts the numbering**
        # (E1) — and the pairings that do fit are still said, for the caller
        # to explain: off by its length…
        self.assertEqual(pair(ep, [(1, 0, 202.0), (4, 0, 202.1)]), ([("t1.1", "f0")], True))
        self.assertEqual(pair(ep, [(2, 0, 212.0), (3, 0, 195.0)]), ([], True))
        # …two files of one number, whichever is as long…
        self.assertEqual(pair(ep, [(1, 0, 202.1), (1, 0, 150.0), (2, 0, 208.4)]),
                         ([("t1.2", "f2")], True))
        # …a slot a better pairing of this import has filled (`filled`),
        # however well the length fits.
        self.assertEqual(pair(ep[1:], [(1, 0, 202.1), (2, 0, 208.4)], ep, filled=ep[:1]),
                         ([("t1.2", "f1")], True))
        # **A track this import does not fill** — the library has it — is
        # checked by its length (E1b): the file that IS that track contradicts
        # nothing and is simply not wanted; one that is not as long does.
        self.assertEqual(pair(ep[1:], [(1, 0, 202.1), (2, 0, 208.4)], ep),
                         ([("t1.2", "f1")], False))
        self.assertEqual(pair(ep[1:], [(1, 0, 150.0), (2, 0, 208.4)], ep),
                         ([("t1.2", "f1")], True))
        self.assertEqual(pair(ep[1:], [(1, 0, 202.1), (1, 0, 202.0), (2, 0, 208.4)], ep),
                         ([("t1.2", "f2")], True))                     # two claim it
        # **A length nobody states testifies to nothing** (E1c), on either
        # side: no pairing for that file, and no contradiction.
        self.assertEqual(pair(ep, [(1, 0, 0), (2, 0, 208.4)]), ([("t1.2", "f1")], False))
        self.assertEqual(pair([slot(1, 0), slot(2, 208.4)], [(1, 0, 202.0), (2, 0, 208.0)]),
                         ([("t1.2", "f1")], False))
        self.assertEqual(pair(ep[1:], [(1, 0, 0), (2, 0, 208.4)], ep), ([("t1.2", "f1")], False))
        # **What contradicts nothing**: no number; a number of no slot of the
        # release (track 9 of six); a disc that names no slot — on one medium
        # a disc that says otherwise, on several none said.
        self.assertEqual(pair(ep, [(0, 0, 202.1), (9, 0, 202.1), (2, 0, 208.4)]),
                         ([("t1.2", "f2")], False))
        self.assertEqual(pair(ep, [(1, 2, 202.1), (2, 1, 208.4)]), ([("t1.2", "f1")], False))
        both = [slot(1, 100, 1, 2), slot(1, 220, 2, 2)]
        self.assertEqual(pair(both, [(1, 0, 100), (1, 2, 220)]), ([("t2.1", "f1")], False))
        self.assertEqual(pair(both, [(1, 2, 100)]), ([], True))
        # What it says of a contradiction names the file and never a path.
        _pairs, against = bot._pair_by_length(ep, [
            {"name": "03 - x.flac", "number": 3, "disc": 0, "length": 60}], ep)
        self.assertIn("“03 - x.flac” is numbered as track 3 and is not as long", against)

    def test_a_files_own_number_is_its_tag_else_what_its_name_leads_with(self):
        own = bot._file_own_number
        self.assertEqual(own({"tracknumber": "3/12"}, "/d/x.flac"), (0, 3))
        self.assertEqual(own({}, "/d/07 - x.flac"), (0, 7))
        self.assertEqual(own({}, "/d/07. x.flac"), (0, 7))
        self.assertEqual(own({}, "/d/x.flac"), (0, 0))
        # **Leads with**: not the first digits anywhere in the name.
        for name in ("U2 - One.flac", "Song (Part 2).flac", "Title [24bit].flac", "Stück 3.flac",
                     "blink-182 - Dammit.flac", "Song.mp3", "2015 - Title.flac", "A1 - Title.flac",
                     # …nor a track word that is only the beginning of a title.
                     "Track 2 of my heart.flac", "Track 01 - Intro.flac", "Tracks 3.flac",
                     "Soundtrack 2.flac", "Track.flac", "Track 2015.flac"):
            with self.subTest(name=name):
                self.assertEqual(own({}, "/d/" + name), (0, 0))
        # **A name that is nothing but a word for "track" and a number has
        # that number** (E1a): what an untagged rip is called.
        for name, number in (("Track 01.flac", 1), ("track_07.flac", 7), ("Titel 3.flac", 3),
                             ("Piste 07.flac", 7), ("Pista 4.opus", 4), ("Traccia 2.flac", 2),
                             ("Spur 5.flac", 5), ("Audiotrack 05.flac", 5),
                             ("Audio Track 12.flac", 12), ("TRACK12.mp3", 12),
                             ("Track-03.flac", 3), ("Track #9.flac", 9)):
            with self.subTest(name=name):
                self.assertEqual(own({}, "/d/" + name), (0, number))
        # …with its disc before it, or in the folder's name; and a tag that
        # says another number leaves it none, as for any name.
        self.assertEqual(own({}, "/d/2-Track 04.flac"), (2, 4))
        self.assertEqual(own({}, "/d/CD2/Track 04.flac"), (2, 4))
        self.assertEqual(own({"tracknumber": "4"}, "/d/Track 04.flac"), (0, 4))
        self.assertEqual(own({"tracknumber": "5"}, "/d/Track 04.flac"), (0, 0))
        self.assertEqual(own({"discnumber": "2", "tracknumber": "4"}, "/d/x.flac"), (2, 4))
        # …after an optional disc prefix; a `CD2` folder says the disc too.
        self.assertEqual(own({}, "/d/2-04 - x.flac"), (2, 4))
        self.assertEqual(own({}, "/d/CD2/04 - x.flac"), (2, 4))
        self.assertEqual(own({"tracknumber": "4"}, "/d/2-04 - x.flac"), (2, 4))
        # **Where the tag and the name both give a number and they differ,
        # the file has none**: nothing is paired on a number it contradicts.
        self.assertEqual(own({"tracknumber": "3/12"}, "/d/07 - x.flac"), (0, 0))
        self.assertEqual(own({"tracknumber": "5"}, "/d/2-04 - x.flac"), (0, 0))
        self.assertEqual(own({"tracknumber": "7"}, "/d/07 - x.flac"), (0, 7))

    def test_a_gap_fill_of_two_rows_from_a_folder_of_exactly_those_two(self):
        # Its slots are the rows it is filling, not the release: two of two.
        self.gap_group((5, 6))
        self.download(AFTER_EP_2_TRACKS[4:], numbered=False)
