    # ── a finalize imports what its transfers landed (ruling C1) ────────────

    def other_copy(self):
        """What an earlier fill of this album left in the folder, refused: a
        copy whose files name the album and no track of it, and are as long
        as none (the review's I-7 folder, a second later)."""
        return [_tiny_flac(os.path.join(self.downloads, f"x{n:02d} - Stück {n}.flac"),
                           seconds=400 + 20 * n,
                           tags={"title": f"Stück {n}", "artist": "After", "album": "After EP 2"})
                for n in range(1, 7)]

    def test_the_next_fill_of_a_folder_files_its_own_six_and_no_other(self):
        # slskd names a local folder after the peer folder's last component:
        # the second peer's "After EP 2" lands beside what the first left.
        told = self.finalize_rig()
        foreign = self.download(OVERWERK_AFTER_HOURS, artist="OVERWERK", album="After Hours EP")
        # (No track numbers on these: "01 - …" twice in one folder is one file.)
        earlier = self.other_copy()
        left = sorted(os.path.basename(p) for p in foreign + earlier)
        right = [_tiny_flac(os.path.join(self.downloads, f"{title}.flac"),
                            seconds=int(round(seconds)),
                            tags={"title": title, "artist": "After", "album": "After EP 2"})
                 for title, seconds in AFTER_EP_2_TRACKS]
        view = self.finalize(right)
        self.assertEqual((view["state"], view["moved"] if "moved" in view else None)[0], "placed",
                         view)
        self.assertEqual(self.in_library(),
                         [f"{n:02d} - {title}.flac"
                          for n, (title, _s) in enumerate(AFTER_EP_2_TRACKS, 1)])
        # The twelve that were not this fill's are as they were — also the
        # six that say they are of this album.
        self.assertEqual(self.in_downloads(), left)
        self.assertEqual(_flac_tags(earlier[0])["title"], ["Stück 1"])
        self.assertEqual(bot._album_fill_get(AFTER_EP_2).get("moved"), 6)
        self.assertIn("present", told)
        # …and a folder that still holds files is still Placement's to list.
        self.assertNotIn(self.downloads, bot._imported_folders)

