    def test_a_fill_whose_files_are_gone_imports_nothing_else(self):
        # Its six were moved away by hand, and the folder holds another
        # copy of the album: an empty selection is "nothing of mine is
        # here", not "everything" — which is what it means to the import.
        told = self.finalize_rig()
        gone = [os.path.join(self.downloads, f"{title}.flac") for title, _s in AFTER_EP_2_TRACKS]
        self.download(AFTER_EP_2_TRACKS)        # "01 - Deep Diving.flac"…: not this fill's
        view = self.finalize(gone)
