    def test_a_transfers_file_outside_its_folder_is_found_only_when_it_is_new(self):
        # slskd may be set up to file downloads some other way: the walk of
        # /downloads is still there, under the same rule.
        self.finalize_rig()
        asked = time.time() - 600
        remote = self.remote("01 - Deep Diving.flac")
        root = os.path.dirname(self.downloads)
        stale = _tiny_flac(os.path.join(root, "aaa", "01 - Deep Diving.flac"))
        os.utime(stale, (time.time() - 3600,) * 2)
