class SharedBucketReconcileTests(ArtistReindexReconcileTests):
    """The re-index looks again at the review groups of the albums it matched —
    not at the groups whose artist is spelled like the one it was run from."""

    RESULT = {"artist_name": "King Gizzard & the Lizard Wizard",
              "review_groups": [{"id": "made"}],
              "releases": [{"status": "complete", "navidrome_album_ids": ["al-1"]}],
              "library": {"album_ids": ["al-1", "al-2"], "artist_ids": ["ar1", "ar2"],
                          "artist_names": ["King Gizzard & the Lizard Wizard",
                                           "King Gizzard and the Lizard Wizard"]}}
    KINO = {"artist_name": "Кино", "review_groups": [], "releases": [],
            "library": {"album_ids": ["al-1"], "artist_ids": ["ar1"],
                        "artist_names": ["Кино"]}}

    @staticmethod
    def _g(gid, album_id, artist="King Gizzard & the Lizard Wizard", origin="library",
           decision="pending"):
        return ArtistReindexReconcileTests._g(gid, album_id, artist, origin, decision)

    def test_a_group_under_the_other_spelling_is_refreshed(self):
        self._seed(self._g("stale", "al-2", artist="King Gizzard and the Lizard Wizard"))
        out = bot._reconcile_artist_review_groups(self.RESULT)
        self.assertEqual(out, {"dropped": [], "refreshed": ["stale"]})

    def test_a_group_is_found_by_its_album_whatever_its_artist_says(self):
        # Built when the album was tagged otherwise: the text is stale, the
        # album is the bucket's.
        self._seed(self._g("stale", "al-2", artist="KGATLW"))
        out = bot._reconcile_artist_review_groups(self.RESULT)
        self.assertEqual(out, {"dropped": [], "refreshed": ["stale"]})

    def test_a_group_under_the_other_spelling_whose_album_is_gone_is_retired(self):
        # Not in the bucket any more — its album is gone — but it names one of
        # the entries the bucket was built from.
        self._seed(self._g("dead", "al-gone", artist="King Gizzard and the Lizard Wizard"))
        out = bot._reconcile_artist_review_groups(self.RESULT)
        self.assertEqual(out, {"dropped": ["dead"], "refreshed": []})

    def test_a_non_latin_artists_groups_are_reconciled_too(self):
        # They were skipped outright: the normalised name was ''.
        self._seed(self._g("stale", "al-1", artist="Кино"),
                   self._g("dead", "al-gone", artist="Кино"),
                   self._g("other", "al-gone2", artist="Алиса"))
        out = bot._reconcile_artist_review_groups(self.KINO)
        self.assertEqual(out, {"dropped": ["dead"], "refreshed": ["stale"]})
        self.assertEqual(self._ids(), ["stale", "other"])

    def test_another_artists_group_is_still_not_looked_at(self):
        self._seed(self._g("theirs", "al-gone", artist="Somebody Else"))
        out = bot._reconcile_artist_review_groups(self.RESULT)
        self.assertEqual((out, self._ids()), ({"dropped": [], "refreshed": []}, ["theirs"]))


