class LibrarySpellingForEveryGrouplessPlacementTests(unittest.TestCase):
    """The library's spelling used to be asked for by one caller, the album
    group's finalize. "Pick the release", a Loose-tracks row's auto-placement,
    an import retry and the Telegram re-import each placed under whatever name
    they were handed — the picked release's credit, or a peer's `albumartist`
    tag — and each could add a second artist to the library that way.

    Real files through the real import; the library spells the artist
    "Belle & Sebastian", and every caller here hands over "Belle and Sebastian".
    """

    MBID = LibrarySpellingForWholeAlbumsTests.MBID
    RELEASE = "0d0d0d0d-1111-2222-3333-444455556666"

    def setUp(self):
        import shutil
        tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, tmp, True)
        self.downloads = os.path.join(tmp, "downloads")
        self.album_dir = os.path.join(self.downloads, "Peer Folder")
        self.lib = os.path.join(tmp, "music")
        os.makedirs(self.lib)
        self.file = _tiny_flac(
            os.path.join(self.album_dir, "01 - One.flac"),
            tags={"title": "One", "artist": PEER_SPELLING, "albumartist": PEER_SPELLING,
                  "album": "Record", "musicbrainz_albumid": self.RELEASE})
        release = _mb_release((_medium(1, "One", "Two"),), self.RELEASE, "Record")
        credit = [{"name": "Belle and Sebastian", "joinphrase": "",
                   "artist": {"id": self.MBID}}]
        self.library = [{"id": "ar1", "name": "Belle & Sebastian", "albumCount": 9,
                         "musicBrainzId": self.MBID}]
        review = isolated_review()
        review.__enter__()
        self.addCleanup(review.__exit__, None, None, None)
        saved = dict(bot._albums)
        self.addCleanup(lambda: (bot._albums.clear(), bot._albums.update(saved)))
        for name, value in (
                ("SLSKD_DOWNLOAD_DIR", self.downloads), ("MUSIC_LIBRARY_PATH", self.lib),
                ("_default_web_user", lambda *a, **k: {}),
                ("mbz_release_tracks", lambda mbid: bot._release_tracks_from(release)),
                ("mbz_release_display", lambda *a, **k: {}),
                ("rgid_from_release", lambda *a, **k: ""),
                ("mbz_get", lambda path, params=None, **k: {"title": "Record",
                                                             "artist-credit": credit}),
                ("_nd_artist_index", lambda *a, **k: list(self.library)),
                ("_nd_scan_after_import", lambda *a, **k: False),
                ("_push_gap", lambda *a, **k: None),
                ("_start_placement_verification", lambda *a, **k: None),
                ("_album_action_markup", lambda *a, **k: None),
                ("_tg_send", AsyncMock()),
                ("_save_state", lambda *a, **k: None),
                ("_task_run", lambda kind, label, target, **k: target("t1") or "t1")):
            patcher = patch.object(bot, name, value)
            patcher.start()
            self.addCleanup(patcher.stop)

    def assert_filed_under_the_librarys_name(self, name="Belle & Sebastian"):
        self.assertEqual(os.listdir(self.lib), [name])
        tags = _flac_tags(os.path.join(self.lib, name, "Record", "01 - One.flac"))
        self.assertEqual((tags["albumartist"], tags["artist"]), ([name], [name]))

    def record(self, **extra):
        bot._albums["rec1"] = {"album_dir": self.album_dir, "release_mbid": self.RELEASE,
                               "artist": "Belle and Sebastian", "album": "Record",
                               "token": "tok", "chat_id": "chat", "label": "B&S - Record",
                               "status": "failed", **extra}

    def test_pick_the_release(self):
        r = _web_app().test_client().post("/api/place-folder", json={
            "path": self.album_dir, "release_mbid": self.RELEASE,
            "artist": "Belle and Sebastian", "album": "Record"})
        self.assertEqual(r.status_code, 200, r.get_json())
        self.assert_filed_under_the_librarys_name()

    def test_a_loose_tracks_auto_placement(self):
        # Its artist is the file's own `albumartist` tag: a peer's spelling.
        with bot._review_lock:
            bot._review_state["groups"] = [{
                "id": "loose1", "group_type": "tracks", "origin": "playlist",
                "artist": "Loose tracks", "album": "Playlist tracks",
                "canonical_mbid": "", "canonical_album_id": "", "albums": [],
                "missing_tracks": [{"title": "One", "artist": "Belle and Sebastian",
                                    "mbid": "rec-One", "decision": "downloaded",
                                    "local_path": self.file}]}]
        self.assertEqual(bot._auto_place_loose_track(self.file, "loose1", 0), "filed")
        self.assert_filed_under_the_librarys_name()

    def test_an_import_retry(self):
        self.record()
        r = _web_app().test_client().post("/api/imports/rec1/retry", json={})
        self.assertEqual((r.status_code, r.get_json()["ok"]), (200, True), r.get_json())
        self.assert_filed_under_the_librarys_name()
        # The answer says where it went.
        self.assertEqual(r.get_json()["import_result"]["artist"], "Belle & Sebastian")

    def test_the_telegram_re_import(self):
        self.record()
        asyncio.run(bot._reimport_worker(None, "rec1", True, self.RELEASE))
        self.assert_filed_under_the_librarys_name()

    def test_a_placement_for_an_album_gap_keeps_the_groups_artist(self):
        # The same folder, placed for a review group: its artist is the
        # library's own name for the album being filled, and is not asked about.
        with bot._review_lock:
            bot._review_state["groups"] = [{
                "id": "g1", "group_type": "", "origin": "library",
                "artist": "Belle and Sebastian", "album": "Record",
                "canonical_mbid": self.RELEASE, "canonical_album_id": "a1", "total": 2,
                "albums": [{"id": "a1", "tracks": [{"title": "Two"}]}],
                # (A row as the pipeline writes one: stamped when it landed.)
                "missing_tracks": [{"title": "One", "artist": "Belle and Sebastian",
                                    "mbid": "rec-One", "position": 1, "disc": 1,
                                    "decision": "downloaded", "local_path": self.file,
                                    "downloaded_at": time.time()}]}]
        asked = []
        with patch.object(bot, "_library_artist_spelling",
                          lambda release, artist: asked.append(artist) or "Somebody Else"):
            self.assertEqual(bot._place_group_downloads("g1")["placed"], 1)
        self.assertEqual(asked, [])
        self.assert_filed_under_the_librarys_name("Belle and Sebastian")

    def test_a_group_that_is_gone_names_no_artist(self):
        # A record still carrying the id of a review group since retired:
        # nothing vouches for the name any more, so it is asked about.
        with bot._group_placement("retired"):
            result = bot._deterministic_album_import(
                self.album_dir, self.RELEASE, "Belle and Sebastian", "Record", "retired")
        self.assertTrue(result["ok"], result)
        self.assert_filed_under_the_librarys_name()

    def test_an_artist_the_library_does_not_have_is_filed_as_handed_over(self):
        self.library = [{"id": "ar9", "name": "Somebody Else", "albumCount": 40,
                         "musicBrainzId": "another"}]
        self.record()
        r = _web_app().test_client().post("/api/imports/rec1/retry", json={})
        self.assertEqual(r.status_code, 200, r.get_json())
        self.assert_filed_under_the_librarys_name("Belle and Sebastian")



class TagSnapshotTests(unittest.TestCase):
    """`_tag_snapshot` / `_tag_restore`: what a tag write can change in a
    file, kept so that it can be put back — the keys written and every alias
    the write deletes (`TAG_ALIASES`)."""

    WRITE = {"title": "Two", "track": "2", "tracktotal": "12", "disc": "1", "disctotal": "1",
             "album": "Record", "year": "1998-09-07", "mb_albumid": "rel-new",
             "mb_releasegroupid": "rg-new", "mb_trackid": "rec-new",
             "mb_releasetrackid": ""}

    def setUp(self):
        import shutil
        self.tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, self.tmp, True)

    def test_a_flac_is_put_back_exactly_aliases_and_absent_keys_included(self):
        seeded = {"title": "Old Title", "tracknumber": "7", "track": "A1", "totaltracks": "6",
                  "discnumber": "2", "disc": "2", "discsubtitle": "Side C", "media": "Vinyl",
                  "album": "Old Album", "musicbrainz_albumid": "rel-old",
                  "musicbrainz_releasetrackid": "peer-track",
                  "artist": "Somebody", "albumartist": "Somebody", "album artist": "Somebody",
                  "genre": ["Rock", "Psychedelic"]}
        path = _tiny_flac(os.path.join(self.tmp, "one.flac"), tags=seeded)
        before = _flac_tags(path)
        snapshot = bot._tag_snapshot(path, bot.ALBUM_OVERRIDE_TAGS)
        self.assertEqual(json.loads(json.dumps(snapshot)), snapshot, "it is stored as JSON")
        self.assertTrue(bot._mutagen_write_tags(path, self.WRITE))
        written = _flac_tags(path)
        self.assertNotEqual(written, before)
        # The write deleted these and created those; the snapshot knows both.
        self.assertFalse({"track", "totaltracks", "disc", "discsubtitle", "media",
                          "musicbrainz_releasetrackid"} & set(written))
        self.assertTrue({"tracktotal", "disctotal", "date", "musicbrainz_trackid",
                         "musicbrainz_releasegroupid"} <= set(written))
        self.assertTrue(bot._tag_restore(path, snapshot))
        self.assertEqual(_flac_tags(path), before)

    def test_the_artist_keys_are_not_in_an_overrides_snapshot(self):
        # An override does not write them, so it neither keeps nor restores them.
        path = _tiny_flac(os.path.join(self.tmp, "one.flac"),
                          tags={"title": "T", "artist": "A", "album artist": "A"})
        snapshot = bot._tag_snapshot(path, bot.ALBUM_OVERRIDE_TAGS)
        self.assertFalse({"artist", "albumartist", "album artist", "artists"}
                         & set(snapshot["tags"]))
        self.assertNotIn("albumartist", bot.ALBUM_OVERRIDE_TAGS)
        self.assertNotIn("artist", bot.ALBUM_OVERRIDE_TAGS)

    def test_a_file_that_cannot_be_read_has_no_snapshot(self):
        path = os.path.join(self.tmp, "broken.flac")
        with open(path, "wb") as fh:
            fh.write(b"not a flac at all")
        self.assertIsNone(bot._tag_snapshot(path, bot.ALBUM_OVERRIDE_TAGS))

    def test_an_mp3s_frames_are_put_back_too(self):
        from mutagen.id3 import ID3, TXXX, TIT2, TRCK, TPOS, TSST, TALB, TPE1, UFID
        path = os.path.join(self.tmp, "one.mp3")
        with open(path, "wb") as fh:
            fh.write(b"\0" * 64)
        seeded = ID3()
        for frame in (TIT2(encoding=3, text=["Old Title"]), TRCK(encoding=3, text=["7/11"]),
                      TPOS(encoding=3, text=["2/2"]), TSST(encoding=3, text=["Side C"]),
                      TALB(encoding=3, text=["Old Album"]), TPE1(encoding=3, text=["Somebody"]),
                      TXXX(encoding=3, desc="TOTALTRACKS", text=["11"]),
                      TXXX(encoding=3, desc="MusicBrainz Album Id", text=["rel-old"]),
                      TXXX(encoding=3, desc="replaygain_track_gain", text=["-6 dB"]),
                      UFID(owner="http://musicbrainz.org", data=b"rec-old")):
            seeded.add(frame)
        seeded.save(path, v2_version=3)

        def frames():
            tag = ID3(path)
            return {key: (getattr(frame, "text", None) and [str(t) for t in frame.text],
                          getattr(frame, "data", None))
                    for key, frame in tag.items()}

        before = frames()
        snapshot = bot._tag_snapshot(path, bot.ALBUM_OVERRIDE_TAGS)
        self.assertEqual(json.loads(json.dumps(snapshot)), snapshot)
        self.assertTrue(bot._mutagen_write_tags(path, dict(self.WRITE, mb_releasetrackid="t-new")))
        self.assertNotEqual(frames(), before)
        self.assertTrue(bot._tag_restore(path, snapshot))
        self.assertEqual(frames(), before)

    def test_an_mp3_with_no_tag_goes_back_to_having_none(self):
        from mutagen.id3 import ID3
        path = os.path.join(self.tmp, "bare.mp3")
        with open(path, "wb") as fh:
            fh.write(b"\0" * 64)
        snapshot = bot._tag_snapshot(path, bot.ALBUM_OVERRIDE_TAGS)
        self.assertTrue(bot._mutagen_write_tags(path, dict(self.WRITE, mb_releasetrackid="t-new")))
        self.assertTrue(ID3(path).keys())
        self.assertTrue(bot._tag_restore(path, snapshot))
        self.assertEqual(list(ID3(path).keys()), [])

    def _mp3(self, name, version, *frames):
        from mutagen.id3 import ID3
        path = os.path.join(self.tmp, name)
        with open(path, "wb") as fh:
            fh.write(b"\0" * 64)
        if frames:
            seeded = ID3()
            for frame in frames:
                seeded.add(frame)
            seeded.save(path, v2_version=version)
        return path

    @staticmethod
    def _id3(path):
        """The tag's version, and every text frame's values."""
        from mutagen.id3 import ID3
        tag = ID3(path)
        return tag.version[:2], {key: [str(t) for t in frame.text]
                                 for key, frame in tag.items() if hasattr(frame, "text")}

    def test_a_v24_mp3_keeps_its_version_and_the_frames_an_override_does_not_own(self):
        # ID3v2.4 holds several values in one text frame; saved as v2.3 they
        # are joined into one ("Artist A/Artist B"). The track artist and the
        # genre are not an override's to touch, and no snapshot keeps them —
        # so the file has to be written, and put back, as the version it is.
        from mutagen.id3 import TIT2, TRCK, TALB, TPE1, TCON, TXXX
        path = self._mp3("two-four.mp3", 4,
                         TIT2(encoding=3, text=["Old Title", "Its Other Title"]),
                         TRCK(encoding=3, text=["7/11"]), TALB(encoding=3, text=["Old Album"]),
                         TPE1(encoding=3, text=["Artist A", "Artist B"]),
                         TCON(encoding=3, text=["Rock", "Psychedelic"]),
                         TXXX(encoding=3, desc="MusicBrainz Album Id", text=["rel-old"]))
        before = self._id3(path)
        self.assertEqual(before[0], (2, 4))
        self.assertEqual(before[1]["TPE1"], ["Artist A", "Artist B"])
        snapshot = bot._tag_snapshot(path, bot.ALBUM_OVERRIDE_TAGS)
        self.assertEqual(json.loads(json.dumps(snapshot)), snapshot)
        self.assertTrue(bot._mutagen_write_tags(path, dict(self.WRITE, mb_releasetrackid="t-new"),
                                                own_id3_version=True))
        version, written = self._id3(path)
        self.assertEqual(version, (2, 4))
        self.assertEqual((written["TIT2"], written["TPE1"], written["TCON"]),
                         (["Two"], ["Artist A", "Artist B"], ["Rock", "Psychedelic"]))
        self.assertTrue(bot._tag_restore(path, snapshot))
        self.assertEqual(self._id3(path), before)

    def test_a_restore_puts_the_version_back_whatever_wrote_in_between(self):
        from mutagen.id3 import TIT2
        path = self._mp3("two-four.mp3", 4, TIT2(encoding=3, text=["Old Title"]))
        snapshot = bot._tag_snapshot(path, bot.ALBUM_OVERRIDE_TAGS)
        self.assertEqual(snapshot["version"], 4)
        self.assertTrue(bot._mutagen_write_tags(path, self.WRITE))       # as placement does
        self.assertEqual(self._id3(path)[0], (2, 3))
        self.assertTrue(bot._tag_restore(path, snapshot))
        self.assertEqual(self._id3(path), ((2, 4), {"TIT2": ["Old Title"]}))

    @staticmethod
    def _id3_raw(path):
        """The tag as it is stored — no translation between versions on load:
        its version, and every frame's own text."""
        from mutagen.id3 import ID3
        tag = ID3(path, translate=False)
        return tag.version[:2], {key: repr(frame) for key, frame in sorted(tag.items())}

    def test_a_v23_mp3_with_several_values_in_a_frame_keeps_them(self):
        # ID3v2.3 has no way to say "two values"; taggers that want one write
        # them NUL-separated all the same (Picard can), and mutagen reads
        # them as two. Saved the ordinary v2.3 way they come back joined by
        # "/": "Artist A/Artist B", "art-1/art-2" — in frames an override does
        # not own, so nothing would put them back.
        from mutagen.id3 import ID3, TIT2, TRCK, TALB, TPE1, TCON, TCOM, TXXX
        path = os.path.join(self.tmp, "two-three-nul.mp3")
        with open(path, "wb") as fh:
            fh.write(b"\0" * 64)
        seeded = ID3()
        for frame in (TIT2(encoding=3, text=["Old Title", "Its Other Title"]),
                      TRCK(encoding=3, text=["7/11"]), TALB(encoding=3, text=["Old Album"]),
                      TPE1(encoding=3, text=["Artist A", "Artist B"]),
                      TCON(encoding=3, text=["Rock", "Psychedelic"]),
                      TCOM(encoding=3, text=["Composer One", "Composer Two"]),
                      TXXX(encoding=3, desc="ARTISTS", text=["Artist A", "Artist B"]),
                      TXXX(encoding=3, desc="MusicBrainz Artist Id", text=["art-1", "art-2"]),
                      TXXX(encoding=3, desc="MusicBrainz Album Id", text=["rel-old"])):
            seeded.add(frame)
        seeded.save(path, v2_version=3, v23_sep=None)
        before = self._id3_raw(path)
        self.assertEqual(before[0], (2, 3))
        self.assertIn("text=['Artist A', 'Artist B']", before[1]["TPE1"])
        snapshot = bot._tag_snapshot(path, bot.ALBUM_OVERRIDE_TAGS)
        self.assertTrue(bot._mutagen_write_tags(path, dict(self.WRITE, mb_releasetrackid="t-new"),
                                                own_id3_version=True))
        version, written = self._id3_raw(path)
        self.assertEqual(version, (2, 3))
        not_ours = ("TPE1", "TCON", "TCOM", "TXXX:ARTISTS", "TXXX:MusicBrainz Artist Id")
        self.assertEqual({key: written[key] for key in not_ours},
                         {key: before[1][key] for key in not_ours})
        self.assertNotEqual(written["TIT2"], before[1]["TIT2"])
        self.assertTrue(bot._tag_restore(path, snapshot))
        self.assertEqual(self._id3_raw(path), before)

    def test_a_v23_mp3_and_one_with_no_tag_are_written_as_v23(self):
        from mutagen.id3 import TIT2, TPE1
        tagged = self._mp3("two-three.mp3", 3, TIT2(encoding=3, text=["Old Title"]),
                           TPE1(encoding=3, text=["Artist A/Artist B"]))
        bare = self._mp3("bare.mp3", 3)
        for path in (tagged, bare):
            snapshot = bot._tag_snapshot(path, bot.ALBUM_OVERRIDE_TAGS)
            self.assertTrue(bot._mutagen_write_tags(path, self.WRITE, own_id3_version=True))
            self.assertEqual(self._id3(path)[0], (2, 3), path)
            self.assertTrue(bot._tag_restore(path, snapshot))
        self.assertEqual(self._id3(tagged), ((2, 3), {"TIT2": ["Old Title"],
                                                      "TPE1": ["Artist A/Artist B"]}))

    def test_placement_still_writes_v23_whatever_the_file_was(self):
        # A file out of /downloads is placement's to tag as it likes (v2.3, for
        # the players that read nothing newer). Only a write that promises to
        # leave the rest of the tag alone asks for the file's own version.
        from mutagen.id3 import TIT2, TPE1
        path = self._mp3("placed.mp3", 4, TIT2(encoding=3, text=["Old Title"]),
                         TPE1(encoding=3, text=["Artist A", "Artist B"]))
        self.assertTrue(bot._mutagen_write_tags(path, self.WRITE))
        # v2.3 as v2.3 is ordinarily written: one value to a frame.
        self.assertEqual(self._id3(path), ((2, 3), {**self._id3(path)[1],
                                                    "TPE1": ["Artist A/Artist B"]}))


class AlbumOverrideMappingTests(unittest.TestCase):
    """`_map_files_to_slots`: which slot of the chosen release each file is.

    In tiers across all the files, never slot by slot: placement's matcher
    walks the slots in order, so a duration match for an earlier slot could
    take a file whose title matched a later one.
    """

    @staticmethod
    def slot(title, mbid="", duration=0, disc=1, position=0):
        return {"title": title, "mbid": mbid, "duration": duration, "disc": disc,
                "position": position}

    @staticmethod
    def file(title, mbids=(), duration=0, disc=0, track=0):
        return {"title": title, "mbids": set(mbids), "duration": duration, "disc": disc,
                "track": track}

    def mapped(self, files, slots):
        got = bot._map_files_to_slots(files, slots)
        return {files[f]["title"] + (f"#{f}" if sum(x["title"] == files[f]["title"]
                                                    for x in files) > 1 else ""):
                (slots[s]["title"], basis) for f, (s, basis) in got.items()}

    def test_a_recording_id_is_read_before_any_title(self):
        slots = [self.slot("Intro", "rec-1"), self.slot("Finale", "rec-2")]
        files = [self.file("Intro", ["rec-2"]),      # mistitled; the id says Finale
                 self.file("Intro")]
        got = bot._map_files_to_slots(files, slots)
        self.assertEqual(got, {0: (1, "mbid"), 1: (0, "exact")})

    def test_a_title_is_read_before_any_duration(self):
        # The fault reported in L2: one file, 200 s, titled for the second
        # slot; the first slot runs 201 s.
        slots = [self.slot("Be Above It", "", 201), self.slot("Beverly Laurel", "", 188)]
        files = [self.file("Beverly Laurel", duration=200)]
        self.assertEqual(self.mapped(files, slots), {"Beverly Laurel": ("Beverly Laurel", "exact")})

    def test_an_exact_title_anywhere_is_read_before_a_looser_one(self):
        slots = [self.slot("Song"), self.slot("Song (Reprise)")]
        files = [self.file("Song (Reprise)"), self.file("Song")]
        self.assertEqual(self.mapped(files, slots),
                         {"Song (Reprise)": ("Song (Reprise)", "exact"), "Song": ("Song", "exact")})

    def test_a_loose_title_loses_to_the_track_that_names_the_file_better(self):
        # "Sing" is inside "Singularity"; the release has a Singularity.
        slots = [self.slot("Sing"), self.slot("Singularity")]
        files = [self.file("Singularity")]
        self.assertEqual(self.mapped(files, slots), {"Singularity": ("Singularity", "exact")})

    def test_of_two_files_the_one_titled_exactly_is_the_slots(self):
        # No other slot claims the live take, so only the order of the tiers
        # keeps it from being taken first.
        slots = [self.slot("Elephant")]
        files = [self.file("Elephant (Live)"), self.file("Elephant")]
        self.assertEqual(bot._map_files_to_slots(files, slots), {1: (0, "exact")})

    def test_two_equally_loose_titles_go_to_the_longer_one(self):
        # Both are a prefix of the file's title; "Singularity" says more of it.
        slots = [self.slot("Sing"), self.slot("Singularity")]
        files = [self.file("Singularity (Live at the Forum)")]
        self.assertEqual(self.mapped(files, slots),
                         {"Singularity (Live at the Forum)": ("Singularity", "prefix")})

    def test_a_title_that_is_a_number_is_a_title(self):
        slots = [self.slot("1979"), self.slot("505"), self.slot("7 Rings")]
        files = [self.file("505"), self.file("7 rings"), self.file("1979")]
        self.assertEqual(self.mapped(files, slots),
                         {"505": ("505", "exact"), "7 rings": ("7 Rings", "exact"),
                          "1979": ("1979", "exact")})

    def test_a_duration_counts_only_when_it_names_one_slot(self):
        slots = [self.slot("惑星", "", 180), self.slot("指切り", "", 300), self.slot("海", "", 302)]
        files = [self.file("Planets", duration=181), self.file("Pinky Swear", duration=301)]
        # 181 s is the first slot's alone; 301 s is two slots' at once.
        self.assertEqual(self.mapped(files, slots), {"Planets": ("惑星", "duration")})

    def test_one_file_per_slot_and_one_slot_per_file(self):
        slots = [self.slot("One", "rec-1"), self.slot("Two", "rec-2")]
        files = [self.file("One", ["rec-1"]), self.file("One", ["rec-1"]), self.file("Two")]
        got = bot._map_files_to_slots(files, slots)
        self.assertEqual(got, {0: (0, "mbid"), 2: (1, "exact")})

    def test_one_title_on_two_discs_goes_by_the_files_own_numbers(self):
        slots = [self.slot("Intro", disc=1, position=1), self.slot("Intro", disc=2, position=1)]
        files = [self.file("Intro", disc=2, track=1), self.file("Intro", disc=1, track=1)]
        self.assertEqual(bot._map_files_to_slots(files, slots),
                         {0: (1, "exact"), 1: (0, "exact")})


# A plain twelve-track release of the same album: the same recordings as the
# box's CD, its own release-track ids.
PLAIN = "1a1a1a1a-2222-3333-4444-555566667777"
PLAIN_MEDIA = ((1, "CD", tuple((f"plain-t{n}", recording, title, ms) for n, (_t, recording, title, ms)
                               in enumerate(LONERISM_MEDIA[2][2], 1))),)
# How the album's twelve songs were numbered on the NAS after eight of them
# were placed as LP sides: disc 1 tracks 1,2,2,3,4,4,5,5,6,6 and disc 3
# tracks 7 and 9. In the CD's song order.
MESSY_NUMBERS = ((1, 1), (1, 2), (1, 3), (1, 4), (1, 5), (1, 6),
                 (3, 7), (1, 2), (3, 9), (1, 4), (1, 5), (1, 6))


def _review_not_flushed(*, urgent: bool = False) -> None:
    """`_save_review_state` for a fixture that does not test the review's
    persistence: the mutation is visible at once, as ever, and nothing is
    written.

    The real one wakes the flusher, a daemon thread that writes
    `bot.REVIEW_FILE` two seconds later — into the temp folder of whichever
    test is running by then. A job that ends with `_task_finish` does that in
    every test of these classes, and the write then races the removal of a
    later test's folder ("Directory not empty", about one run in four once the
    merge's tests followed the override's)."""
    bot._invalidate_review_snapshot()


class _FakeNavidrome:
    """Navidrome over a folder of real files: one album per release id in the
    files' tags, read from the disk again at every scan — so an album's id
    follows its release, as Navidrome's does.

    A scan is asked for with `scan` (`startScan`) and has run when `finish`
    says so: at once while `auto` is on, when the test calls it otherwise.
    Until then `status` reads `scanning` and the albums are the ones the last
    scan found. `synthesized` is Navidrome with "Report Real Path" off for
    lb-bot's player, which is how the live one was found: every song's path is
    made up from its tags."""

    def __init__(self, lib):
        self.lib, self.albums, self.scans, self.auto, self.down = lib, {}, 0, True, False
        self.scanning, self.finished, self.synthesized, self.admin = False, 0, False, True

    def scan(self, *a, **k):
        self.scans += 1
        if not self.admin:
            return False                # `startScan` is an admin's to ask for
        if self.scanning:
            return True                 # one at a time: this one starts nothing
        self.scanning = True
        if self.auto:
            self.finish()
        return True

    def finish(self):
        """The scan that was running (or one of Navidrome's own) ends."""
        self.index()
        self.scanning, self.finished = False, self.finished + 1
        return self

    def status(self, *a, **k):
        """`getScanStatus`, as `nd_get_scan_status` hands it on."""
        if self.down:
            return {}
        return {"scanning": self.scanning, "count": 12,
                "lastScan": f"2026-10-10T00:00:{self.finished:02d}Z"}

    def reported(self, path, tags):
        """The path Navidrome answers for a song."""
        if not self.synthesized:
            return path
        # server/subsonic/helpers.go, fakePath: album artist / album /
        # DD-TT - Title.ext, with every "/" in a name made a "_".
        clean = lambda text: (text or "").replace("/", "_")
        disc = int((tags.get("discnumber") or "0").split("/")[0] or 0)
        track = int((tags.get("tracknumber") or "0").split("/")[0] or 0)
        name = (f"{disc:02d}-" if disc else "") + (f"{track:02d} - " if track else "")
        return (f"{clean(tags.get('albumartist'))}/{clean(tags.get('album'))}/"
                f"{name}{clean(tags.get('title'))}.{path.rsplit('.', 1)[-1]}")

    def index(self):
        import hashlib
        self.albums = {}
        for root, _dirs, names in os.walk(self.lib):
            for name in sorted(names):
                if not name.endswith(".flac"):
                    continue
                path = os.path.join(root, name)
                try:
                    tags = {k: v[0] for k, v in _flac_tags(path).items()}
                except Exception:  # noqa: BLE001 — a file it cannot read is not listed
                    continue
                release = tags.get("musicbrainz_albumid", "")
                title = tags.get("album", os.path.basename(root))
                # By what the files say, not by where they are: an album kept
                # in disc subfolders is one album.
                album_id = "al-" + hashlib.md5(f"{release}|{title}".encode()).hexdigest()[:10]
                album = self.albums.setdefault(album_id, {
                    "id": album_id, "name": title, "artist": tags.get("albumartist", ""),
                    "artistId": "ar1", "musicBrainzId": release, "song": []})
                album["song"].append({
                    "id": "s-" + name, "title": tags.get("title", name),
                    "track": int((tags.get("tracknumber") or "0").split("/")[0] or 0),
                    "discNumber": int((tags.get("discnumber") or "1").split("/")[0] or 1),
                    "duration": 200, "path": self.reported(path, tags), "albumId": album_id,
                    "artistId": "ar1"})
        return self

    def album(self, album_id):
        if self.down:
            raise bot.NavidromeUnavailable("Navidrome did not answer (ConnectionError)")
        album = self.albums.get(album_id)
        return json.loads(json.dumps(album)) if album else None

    def search(self, name):
        if self.down:
            raise bot.NavidromeUnavailable("Navidrome did not answer (ConnectionError)")
        return [{k: v for k, v in album.items() if k != "song"}
                for album in self.albums.values() if name.lower() in album["name"].lower()]

    def only(self):
        (album,) = self.albums.values()
        return album


class _OverridableAlbum:
    """Lonerism in a temp library as it sat on the NAS — twelve real FLAC
    files tagged with the box (d105e2cd) and numbered as LP sides — behind a
    fake Navidrome and a fake MusicBrainz. Tasks run inline."""

    def setUp(self):
        import shutil
        tmp = tempfile.mkdtemp()
        self.addCleanup(shutil.rmtree, tmp, True)
        self.tmp = tmp
        self.lib = os.path.join(tmp, "music")
        self.folder = os.path.join(self.lib, "Tame Impala", "Lonerism")
        review = isolated_review()
        review.__enter__()
        self.addCleanup(review.__exit__, None, None, None)
        saved = (bot.pending_album_groups.copy(), bot.pending_downloads.copy(),
                 bot._album_fill_status.copy())

        def restore():
            for live, old in zip((bot.pending_album_groups, bot.pending_downloads,
                                  bot._album_fill_status), saved):
                live.clear()
                live.update(old)

        self.addCleanup(restore)
        for table in (bot.pending_album_groups, bot.pending_downloads, bot._album_fill_status):
            table.clear()
        self.songs = [title for _t, _r, title, _ms in LONERISM_MEDIA[2][2]]
        for n, ((_track, recording, title, _ms), (disc, track)) in enumerate(
                zip(LONERISM_MEDIA[2][2], MESSY_NUMBERS), 1):
            tags = {"title": title, "tracknumber": str(track), "tracktotal": "6",
                    "discnumber": str(disc), "disctotal": "4", "album": "Lonerism",
                    "albumartist": "Tame Impala", "artist": "Tame Impala", "date": "2012",
                    "musicbrainz_albumid": LONERISM, "musicbrainz_trackid": recording,
                    "musicbrainz_releasetrackid": f"lp-side-{n}",
                    # what the peer's tagger left beside them
                    "totaltracks": "6", "disc": str(disc)}
            if n in (3, 6):
                del tags["musicbrainz_trackid"]          # found by title
            if n == 6:
                tags["title"] = "Why Won't They Talk To Me?"   # a peer's punctuation
            _tiny_flac(os.path.join(self.folder, f"{disc}-{track:02d} - song {n}.flac"), tags=tags)
        self.nd = _FakeNavidrome(self.lib).index()
        self.old_id = self.nd.only()["id"]
        self.releases = {
            LONERISM: dict(_mb_release(LONERISM_MEDIA, LONERISM, "Lonerism"),
                           date="2012", country="XE", disambiguation="Deluxe Limited Edition"),
            PLAIN: dict(_mb_release(PLAIN_MEDIA, PLAIN, "Lonerism"),
                        date="2012-10-05", country="AU", disambiguation="")}
        self.rgids = {LONERISM: "rg-lonerism", PLAIN: "rg-lonerism"}
        self.mb_down, self.mb_asked = False, []
        self.notified, self.refreshed, self.images = [], [], {}
        # Each wait between two looks at Navidrome: what the row read then.
        self.waits, self.at_wait = [], {}
        jobs = getattr(bot, "_album_override_jobs", None)
        if jobs is not None:
            self.addCleanup(jobs.clear)

        def mbz_get(path, params=None, strict=False, **k):
            kind, _, mbid = path.partition("/")
            if self.mb_down:
                if strict:
                    raise bot.MusicBrainzUnavailable("MusicBrainz did not answer (503)")
                return {}
            doc = self.releases.get(mbid) if kind == "release" else None
            self.mb_asked.append((path, (params or {}).get("inc", "")))
            if doc is None:
                if strict:
                    raise bot.MusicBrainzNoSuchEntity("MusicBrainz has no such entity")
                return {}
            # As MusicBrainz answers: the parts the `inc` names, in one document.
            incs = (params or {}).get("inc", "").split()
            group = {"release-group": {"id": self.rgids[mbid]}} if "release-groups" in incs else {}
            return {**doc, **group} if "recordings" in incs else {"id": mbid, **group}

        def fetch(url):
            if url not in self.images:
                raise bot.CoverArchiveUnavailable("the Cover Art Archive did not answer")
            return self.images[url]

        for name, value in (
                ("MUSIC_LIBRARY_PATH", self.lib),
                ("_default_web_user", lambda *a, **k: {"navidrome_user": "u",
                                                       "navidrome_password": "p",
                                                       "telegram_token": ""}),
                ("_nd_album", self.nd.album),
                ("_nd_search_albums", self.nd.search),
                ("nd_start_scan", self.nd.scan),
                ("nd_get_scan_status", self.nd.status),
                ("_nd_artist_index", lambda *a, **k: [{"id": "ar1", "name": "Tame Impala",
                                                       "musicBrainzId": "artist-mbid"}]),
                ("mbz_get", mbz_get),
                ("_fetch_cover_image", fetch),
                ("_album_override_pause", self._pause),
                ("_notify_hub_library_change",
                 lambda mbid, **k: self.notified.append((mbid, k))),
                ("_artist_release_refresh_view",
                 lambda data: self.refreshed.append(dict(data)) or ({"ok": True}, 200)),
                ("_save_review_state", _review_not_flushed),
                ("_task_run", lambda kind, label, target, **k: target("t1") or "t1")):
            patcher = patch.object(bot, name, value)
            patcher.start()
            self.addCleanup(patcher.stop)

    def song(self, n):
        """The path of the album's n-th song, however its file is numbered."""
        (name,) = [name for name in os.listdir(self.folder) if name.endswith(f"song {n}.flac")]
        return os.path.join(self.folder, name)

    def singles(self):
        """Two untagged singles kept loose in an artist's folder, which has a
        picture of its own: two albums to Navidrome, one folder. Returns the
        folder and the two album ids."""
        folder = os.path.join(self.lib, "Some Artist")
        for title in ("Single One", "Single Two"):
            _tiny_flac(os.path.join(folder, title.lower() + ".flac"),
                       tags={"title": title, "album": title, "artist": "Some Artist",
                             "albumartist": "Some Artist", "tracknumber": "1"})
        with open(os.path.join(folder, "folder.jpg"), "wb") as fh:
            fh.write(b"the artist's own picture")
        self.nd.index()
        ids = {album["name"]: album["id"] for album in self.nd.albums.values()}
        return folder, ids["Single One"], ids["Single Two"]

    def _pause(self, seconds):
        """Instead of sleeping between two looks at Navidrome: note what the
        row reads, and do what the test put at this wait (`self.at_wait[n]`,
        counted from 1)."""
        rows = self.rows()
        self.waits.append((rows[0]["state"], rows[0]["album_id"]) if rows else ("gone", ""))
        then = self.at_wait.get(len(self.waits))
        if then:
            then()

    # ── what is on disk ─────────────────────────────────────────────────────

    def tags(self):
        """{song number: its tags}, by the CD's song order."""
        out = {}
        for name in sorted(os.listdir(self.folder)):
            if name.endswith(".flac"):
                out[int(name.rsplit("song ", 1)[1].split(".")[0])] = _flac_tags(
                    os.path.join(self.folder, name))
        return out

    def numbers(self):
        return {n: (int(t["discnumber"][0]), int(t["tracknumber"][0]))
                for n, t in self.tags().items()}

    def snapshots(self):
        with bot._index_lock:
            return [dict(r) for r in bot._index_db().execute(
                "SELECT batch_id, path, before FROM tag_changes ORDER BY path")]

    def rows(self):
        with bot._index_lock:
            return [dict(r) for r in bot._index_db().execute(
                "SELECT * FROM album_overrides ORDER BY set_at")]

    # ── the routes' functions ───────────────────────────────────────────────

    def apply(self, release=PLAIN, album_id=None, **body):
        return bot._album_override_apply_view(
            {"album_id": self.old_id if album_id is None else album_id,
             "release_mbid": release, **body})

    def applied(self, release=PLAIN, **body):
        payload, status = self.apply(release, **body)
        self.assertEqual((status, payload.get("state")), (200, "applying"), payload)
        return payload["id"]

    def state(self, **by):
        return bot._album_state_view(by.get("album_id", ""), by.get("id", ""))

    def row(self, override_id):
        payload, status = self.state(id=override_id)
        self.assertEqual(status, 200, payload)
        return payload["override"]


class AlbumOverridePreviewTests(_OverridableAlbum, unittest.TestCase):
    """`POST /api/album/override/preview`: what an apply would do, and nothing done."""

    def preview(self, release=PLAIN, album_id=None):
        return bot._album_override_preview_view(
            {"album_id": self.old_id if album_id is None else album_id, "release_mbid": release})

    def test_the_lonerism_files_map_to_tracks_one_to_twelve(self):
        before = self.tags()
        payload, status = self.preview()
        self.assertEqual(status, 200, payload)
        self.assertEqual(sorted(payload), ["albumId", "files", "matched", "missing",
                                           "release", "releaseMbid", "unmatched"])
        self.assertEqual((payload["albumId"], payload["releaseMbid"]), (self.old_id, PLAIN))
        self.assertEqual(payload["release"], {
            "title": "Lonerism", "disambiguation": "", "year": "2012", "country": "AU",
            "format": "CD", "trackCount": 12, "discCount": 1})
        self.assertEqual((payload["matched"], payload["unmatched"], payload["missing"]),
                         (12, 0, []))
        by_title = {f["to"]["title"]: f for f in payload["files"]}
        self.assertEqual([by_title[t]["to"] for t in self.songs],
                         [{"disc": 1, "track": n, "title": t} for n, t in enumerate(self.songs, 1)])
        # Where each came from, as the file is tagged now.
        self.assertEqual([(by_title[t]["from"]["disc"], by_title[t]["from"]["track"])
                          for t in self.songs], list(MESSY_NUMBERS))
        self.assertEqual(by_title[self.songs[5]]["from"]["title"], "Why Won't They Talk To Me?")
        self.assertEqual({t: by_title[t]["basis"] for t in self.songs},
                         {t: ("exact" if n in (3, 6) else "mbid")
                          for n, t in enumerate(self.songs, 1)})
        self.assertEqual({f["changed"] for f in payload["files"]}, {True})
        # Each row has exactly the contract's keys, and the numbers are whole.
        for f in payload["files"]:
            self.assertEqual(sorted(f), ["basis", "changed", "from", "to"])
            for side in (f["from"], f["to"]):
                self.assertEqual(sorted(side), ["disc", "title", "track"])
                self.assertIs(type(side["disc"]), int)
                self.assertIs(type(side["track"]), int)
        # Nothing was written, and nothing was kept.
        self.assertEqual(self.tags(), before)
        self.assertEqual((self.snapshots(), self.rows()), ([], []))

    def test_no_path_goes_on_the_wire(self):
        payload, _ = self.preview()
        self.assertNotIn(self.tmp, json.dumps(payload))
        self.assertNotIn(".flac", json.dumps(payload))

    def test_the_release_is_one_musicbrainz_request(self):
        # Its tracklist and its release group are one document. Asked for
        # separately, strictly, an unhappy MusicBrainz cost twice the wait —
        # past the hub's timeout, with an apply then starting that nobody
        # was following (F8).
        payload, status = self.preview()
        self.assertEqual((status, payload["release"]["trackCount"]), (200, 12))
        self.assertEqual(self.mb_asked, [(f"release/{PLAIN}", "release-groups recordings")])
        self.assertEqual(bot._album_release(PLAIN)["rgid"], "rg-lonerism")

    def test_a_file_with_no_slot_is_listed_and_the_empty_slots_are_named(self):
        _tiny_flac(os.path.join(self.folder, "9-99 - song 13.flac"),
                   tags={"title": "A Hidden Demo", "tracknumber": "99", "discnumber": "9",
                         "album": "Lonerism", "albumartist": "Tame Impala",
                         "musicbrainz_albumid": LONERISM})
        os.remove(os.path.join(self.folder, "1-01 - song 1.flac"))
        self.nd.index()
        payload, status = self.preview(album_id=self.nd.only()["id"])
        self.assertEqual((status, payload["matched"], payload["unmatched"]), (200, 11, 1))
        stray = next(f for f in payload["files"] if f["to"] is None)
        self.assertEqual(stray, {"from": {"disc": 9, "track": 99, "title": "A Hidden Demo"},
                                 "to": None, "basis": "", "changed": False})
        self.assertEqual(payload["missing"], [{"disc": 1, "track": 1, "title": "Be Above It"}])

    def test_a_file_already_as_the_slot_says_is_not_a_change(self):
        # Two files already say they are the release. The first also has the
        # slot's numbers; the seventh still says disc 3.
        for name in ("1-01 - song 1.flac", "3-07 - song 7.flac"):
            bot._mutagen_write_tags(os.path.join(self.folder, name), {"mb_albumid": PLAIN})
        self.nd.index()
        (album_id,) = [a["id"] for a in self.nd.albums.values() if a["musicBrainzId"] == PLAIN]
        payload, _ = self.preview(album_id=album_id)
        self.assertEqual([(f["to"]["track"], f["basis"], f["changed"]) for f in payload["files"]],
                         [(1, "mbid", False), (7, "mbid", True)])

    def test_what_is_refused(self):
        def code(payload, status):
            self.assertTrue(payload.get("error"), payload)
            return status, payload.get("code", ""), bool(payload.get("retryable"))

        view = bot._album_override_preview_view
        self.assertEqual(code(*view({"release_mbid": PLAIN})), (400, "", False))
        self.assertEqual(code(*view({"album_id": self.old_id})), (400, "", False))
        self.assertEqual(code(*view({"album_id": self.old_id, "release_mbid":
                                     f"https://musicbrainz.org/release/{PLAIN}"})),
                         (400, "", False))
        self.assertEqual(code(*self.preview(album_id="no-such-album")),
                         (404, "unknown_album", False))
        self.assertEqual(code(*self.preview("9f9f9f9f-0000-0000-0000-000000000000")),
                         (404, "unknown_release", False))
        self.mb_down = True
        self.assertEqual(code(*self.preview()), (502, "", True))
        self.mb_down, self.nd.down = False, True
        self.assertEqual(code(*self.preview()), (502, "", True))


class AlbumOverrideApplyTests(_OverridableAlbum, unittest.TestCase):
    """`POST /api/album/override` and `…/remove`: the retag, and its undo."""

    def test_apply_retags_every_file_to_its_slot_and_renames_nothing(self):
        names = sorted(os.listdir(self.folder))
        payload, status = self.apply()
        self.assertEqual((status, sorted(payload)), (200, ["id", "ok", "state"]))
        self.assertEqual((payload["ok"], payload["state"]), (True, "applying"))
        self.assertEqual(sorted(os.listdir(self.folder)), names)
        tags = self.tags()
        self.assertEqual(self.numbers(), {n: (1, n) for n in range(1, 13)})
        for n, (_t, recording, title, _ms) in enumerate(LONERISM_MEDIA[2][2], 1):
            self.assertEqual(
                {k: tags[n][k] for k in ("title", "tracktotal", "disctotal", "album", "date",
                                         "musicbrainz_albumid", "musicbrainz_releasegroupid",
                                         "musicbrainz_trackid", "musicbrainz_releasetrackid")},
                {"title": [title], "tracktotal": ["12"], "disctotal": ["1"],
                 "album": ["Lonerism"], "date": ["2012-10-05"],
                 "musicbrainz_albumid": [PLAIN], "musicbrainz_releasegroupid": ["rg-lonerism"],
                 "musicbrainz_trackid": [recording], "musicbrainz_releasetrackid": [f"plain-t{n}"]})
            # The peer's other names for the numbers went with the write (L2b)…
            self.assertFalse({"totaltracks", "disc"} & set(tags[n]))
            # …and who the album is by is not this feature's to say.
            self.assertEqual((tags[n]["albumartist"], tags[n]["artist"]),
                             (["Tame Impala"], ["Tame Impala"]))

    def test_the_row_ends_applied_with_the_albums_new_id(self):
        override_id = self.applied()
        row = self.row(override_id)
        new_id = self.nd.only()["id"]
        self.assertNotEqual(new_id, self.old_id)
        self.assertEqual(sorted(row), ["album", "albumId", "artist", "coverUrl", "done",
                                       "failures", "id", "prevReleaseMbid", "releaseMbid",
                                       "rgid", "setAt", "state", "total"])
        self.assertEqual({k: row[k] for k in row if k not in ("setAt",)}, {
            "id": override_id, "state": "applied", "releaseMbid": PLAIN,
            "prevReleaseMbid": LONERISM, "rgid": "rg-lonerism", "artist": "Tame Impala",
            "album": "Lonerism", "albumId": new_id, "coverUrl": "", "done": 12, "total": 12,
            "failures": []})
        self.assertIs(type(row["done"]), int)
        self.assertGreater(row["setAt"], time.time() - 60)
        self.assertEqual(self.nd.scans, 1)

    def test_every_file_is_kept_before_any_file_is_written(self):
        # All of them, before the first write — a job that stops half way has
        # every file it touched on record, and so has a power cut.
        order = []
        real_write = bot._mutagen_write_tags

        def write(path, tags, **k):
            with bot._index_lock:
                conn = bot._index_db()
                kept = conn.execute("SELECT COUNT(*) FROM tag_changes").fetchone()[0]
                mine = conn.execute("SELECT COUNT(*) FROM tag_changes WHERE path = ?",
                                    (path,)).fetchone()[0]
            order.append((kept, mine))
            return real_write(path, tags, **k)

        with patch.object(bot, "_mutagen_write_tags", write):
            self.applied()
        self.assertEqual(order, [(12, 1)] * 12)
        self.assertEqual(len(self.snapshots()), 12)

    def test_the_snapshots_are_on_disk_before_the_first_write(self):
        # The index is WAL with synchronous=NORMAL: a commit is not on disk
        # until the next checkpoint. The one that keeps the files' tags is
        # made with synchronous=FULL, and the setting is put back.
        said = []
        with bot._index_lock:
            conn = bot._index_db()
        real_write = bot._mutagen_write_tags

        def write(path, tags, **k):
            said.append("WRITE")
            return real_write(path, tags, **k)

        conn.set_trace_callback(lambda sql: said.append(" ".join(sql.split())))
        self.addCleanup(conn.set_trace_callback, None)
        with patch.object(bot, "_mutagen_write_tags", write):
            self.applied()
        conn.set_trace_callback(None)
        first_write = said.index("WRITE")
        before = said[:first_write]
        inserts = [i for i, sql in enumerate(before) if sql.startswith("INSERT OR IGNORE INTO tag_changes")]
        self.assertEqual(len(inserts), 12)
        full = max(i for i, sql in enumerate(before) if sql == "PRAGMA synchronous=FULL")
        commit = min(i for i, sql in enumerate(before) if sql == "COMMIT" and i > inserts[-1])
        normal = min(i for i, sql in enumerate(before) if sql == "PRAGMA synchronous=NORMAL" and i > full)
        self.assertLess(full, inserts[0])
        self.assertLess(inserts[-1], commit)
        self.assertLess(commit, normal, "FULL is still in force when the snapshots are committed")
        # The row itself — what an undo is asked for by — was made the same way.
        said = [sql for sql in before if not sql.startswith("BEGIN")]
        row = next(i for i, sql in enumerate(said) if sql.startswith("INSERT INTO album_overrides"))
        self.assertEqual((said[row - 1], said[row + 1], said[row + 2]),
                         ("PRAGMA synchronous=FULL", "COMMIT", "PRAGMA synchronous=NORMAL"))
        # One transaction for the twelve, not twelve.
        self.assertFalse([sql for sql in before[inserts[0]:inserts[-1]] if sql == "COMMIT"])
        with bot._index_lock:
            self.assertEqual(conn.execute("PRAGMA synchronous").fetchone()[0], 1)   # NORMAL

    def test_snapshots_that_cannot_be_kept_mean_nothing_is_written(self):
        before = self.tags()

        def keep(batch_id, entries):
            raise sqlite3.OperationalError("database or disk is full")

        with patch.object(bot, "_tag_changes_keep_all", keep):
            override_id = self.applied()
        row = self.row(override_id)
        self.assertEqual((row["state"], row["done"]), ("failed", 0))
        self.assertEqual(row["failures"], [{
            "title": "Lonerism",
            "reason": "the files' earlier tags could not be kept, so nothing was written"}])
        self.assertEqual((self.tags(), self.snapshots()), (before, []))

    def test_a_file_is_written_as_the_tag_version_it_has(self):
        # An MP3's ID3 version: see TagSnapshotTests. The override asks for it.
        asked = []
        real_write = bot._mutagen_write_tags

        def write(path, tags, **k):
            asked.append(k)
            return real_write(path, tags, **k)

        with patch.object(bot, "_mutagen_write_tags", write):
            self.applied()
        self.assertEqual(asked, [{"own_id3_version": True}] * 12)

    def test_remove_puts_every_tag_back_the_deleted_aliases_included(self):
        before = self.tags()
        override_id = self.applied()
        self.assertNotEqual(self.tags(), before)
        payload, status = bot._album_override_remove_view({"id": override_id})
        self.assertEqual((status, payload), (200, {"ok": True, "id": override_id,
                                                    "state": "removing"}))
        self.assertEqual(self.tags(), before)
        self.assertEqual(before[1]["totaltracks"], ["6"], "an alias the write had deleted")
        # The row is gone — which is how a poll learns the remove finished.
        gone, status = self.state(id=override_id)
        self.assertEqual((status, gone.get("code")), (404, "no_override"))
        self.assertEqual((self.rows(), self.snapshots()), ([], []))
        self.assertEqual(self.nd.only()["id"], self.old_id)

    def test_a_second_apply_keeps_the_first_snapshot(self):
        before = self.tags()
        other = "2b2b2b2b-2222-3333-4444-555566667777"
        self.releases[other] = dict(_mb_release(
            ((1, "Digital Media", tuple((f"other-t{n}", rec, title, ms) for n, (_t, rec, title, ms)
                                        in enumerate(reversed(LONERISM_MEDIA[2][2]), 1))),),
            other, "Lonerism (Reversed)"), date="2020", country="XW", disambiguation="")
        self.rgids[other] = "rg-other"
        # The first release has no date, so its apply writes none — and the
        # second's does. What was kept the first time has to cover that too.
        self.releases[PLAIN]["date"] = ""
        first = self.applied()
        self.assertEqual(self.tags()[1]["date"], ["2012"])
        kept = self.snapshots()
        again, status = self.apply(other, album_id=self.nd.only()["id"])
        self.assertEqual((status, again["id"]), (200, first), "the same row, not a second one")
        self.assertEqual(self.numbers(), {n: (1, 13 - n) for n in range(1, 13)})
        self.assertEqual(self.tags()[1]["date"], ["2020"])
        self.assertEqual(self.snapshots(), kept)
        row = self.row(first)
        self.assertEqual((row["releaseMbid"], row["prevReleaseMbid"], row["rgid"], row["album"]),
                         (other, LONERISM, "rg-other", "Lonerism (Reversed)"))
        self.assertEqual(len(self.rows()), 1)
        # And the undo goes back past both.
        self.assertEqual(bot._album_override_remove_view({"id": first})[1], 200)
        self.assertEqual(self.tags(), before)

    def test_the_same_release_again_writes_nothing(self):
        first = self.applied()
        new_id = self.nd.only()["id"]
        kept, tags = self.snapshots(), self.tags()
        again, status = self.apply(album_id=new_id)
        self.assertEqual((status, again["id"]), (200, first))
        row = self.row(first)
        # Every file already is what the release says: nothing to write, and
        # the album keeps the id it has.
        self.assertEqual((row["state"], row["done"], row["total"], row["albumId"]),
                         ("applied", 0, 0, new_id))
        self.assertEqual((self.snapshots(), self.tags()), (kept, tags))

    def test_a_job_that_dies_does_not_leave_the_row_applying(self):
        calls = []
        real_write = bot._mutagen_write_tags

        def write(path, tags, **k):
            calls.append(path)
            if len(calls) == 5:
                raise RuntimeError("the disk went away")
            return real_write(path, tags, **k)

        def task_run(kind, label, target, **k):
            # As the real one: the error is the task's, not the request's.
            try:
                target("t1")
            except Exception:  # noqa: BLE001
                pass
            return "t1"

        self.gap()
        with patch.object(bot, "_mutagen_write_tags", write), \
                patch.object(bot, "_task_run", task_run):
            override_id = self.applied()
        row = self.row(override_id)
        self.assertEqual((row["state"], row["done"], row["total"]), ("failed", 4, 12))
        self.assertEqual(row["failures"], [{
            "title": "Lonerism",
            "reason": "stopped by an error (RuntimeError) — undo to restore the previous tags, "
                      "or apply again"}])
        # It let go of the album: the claim, and the hold on Fill gaps.
        self.assertFalse(bot._group_placement_active("g1"))
        self.assertFalse(bot._album_override_running_for({self.old_id}))
        # The four that were written can be put back.
        self.assertEqual(bot._album_override_remove_view({"id": override_id})[1], 200)
        self.assertEqual(self.numbers(), dict(zip(range(1, 13), MESSY_NUMBERS)))

    def test_a_file_whose_tags_cannot_be_read_is_not_written(self):
        # No record of what it was, no write — even though the write itself
        # would have gone through.
        real = bot._tag_snapshot
        before = self.tags()
        with patch.object(bot, "_tag_snapshot",
                          lambda path, keys: None if "song 4." in path else real(path, keys)):
            override_id = self.applied()
        row = self.row(override_id)
        self.assertEqual((row["state"], row["done"], row["total"]), ("applied", 11, 12))
        self.assertEqual(row["failures"], [{
            "title": "Mind Mischief",
            "reason": "its tags could not be read, so it was left as it is"}])
        self.assertEqual(self.tags()[4], before[4])
        self.assertEqual(len(self.snapshots()), 11)

    def test_a_file_that_cannot_be_written_is_a_failure_and_the_rest_go_on(self):
        real = bot._mutagen_write_tags
        with patch.object(bot, "_mutagen_write_tags",
                          lambda path, tags, **k: (False if "song 4." in path
                                                   else real(path, tags, **k))):
            override_id = self.applied()
        row = self.row(override_id)
        self.assertEqual((row["state"], row["done"], row["total"]), ("applied", 11, 12))
        self.assertEqual(row["failures"], [{"title": "Mind Mischief",
                                            "reason": "its tags could not be written"}])
        self.assertEqual(self.numbers()[4], MESSY_NUMBERS[3])
        self.assertEqual(self.numbers()[5], (1, 5))
        # The album again is the one that holds the eleven that were written;
        # the twelfth is not waited for.
        (retagged,) = [a for a in self.nd.albums.values() if a["musicBrainzId"] == PLAIN]
        self.assertEqual((len(retagged["song"]), row["albumId"]), (11, retagged["id"]))

    # ── the guards ──────────────────────────────────────────────────────────

    def refused(self, payload, status):
        self.assertTrue(payload.get("error"), payload)
        return status, payload.get("code", "")

    def test_fewer_than_half_the_files_matching_needs_force(self):
        seven = tuple(LONERISM_MEDIA[2][2][:5]) + (
            ("x-t6", "x-rec-6", "Something Else", 100000), ("x-t7", "x-rec-7", "Another", 110000))
        short = "3c3c3c3c-2222-3333-4444-555566667777"
        self.releases[short] = dict(_mb_release(((1, "CD", seven),), short, "Lonerism EP"),
                                    date="2013", country="US", disambiguation="")
        self.rgids[short] = "rg-ep"
        before = self.tags()
        payload, status = self.apply(short)
        self.assertEqual((status, payload.get("code"), payload.get("matched"), payload.get("total")),
                         (409, "poor_match", 5, 12))
        self.assertIs(type(payload["matched"]), int)
        self.assertEqual((self.tags(), self.rows()), (before, []))
        # A string is not the confirmation.
        self.assertEqual(self.apply(short, force="true")[1], 409)
        override_id = self.applied(short, force=True)
        row = self.row(override_id)
        self.assertEqual((row["state"], row["done"], row["total"]), ("applied", 5, 5))
        after = self.tags()
