    def test_the_look_for_the_album_stops_when_the_row_has_moved_on(self):
        # Navidrome is slow, and the user undoes the override (or applies
        # another release) while lb-bot is still looking for the album's new
        # id. That look is the earlier job's: it writes nothing more.
        self.nd.auto = False

        def undo():                     # past the minute: `applied`, still looking
            with bot._index_lock, bot._index_db() as conn:
                conn.execute("UPDATE album_overrides SET state = 'removing'")
            self.nd.finish()            # …and now the retagged album is listed

        self.at_wait[30] = undo
        self.applied()
        self.assertEqual(len(self.waits), 30)
        row = self.rows()[0]
        self.assertEqual((row["state"], row["album_id"]), ("removing", ""))
        self.assertEqual((self.notified, self.refreshed), ([], []))

    def test_the_look_is_its_own_jobs_and_not_the_next_ones(self):
        # Navidrome is slow: the first apply ends `applied` with no id and
        # lb-bot goes on looking. The user applies again — the same release,
        # the same row — and that job finds the album and says so everywhere.
        # The first job's look, still running, finds the very same album, on a
        # row that reads `applied`: it is not that job's row any more (the
        # apply stamped it anew), and it must not announce the album again.
        self.nd.auto = False
        self.gap()
        again = []

        def apply_again():
            self.nd.finish()                        # the first scan ends at last
            self.nd.auto = True
            again.append(self.apply(album_id=self.nd.only()["id"]))

        self.at_wait[30] = apply_again
        first = self.applied()
        (payload, status), = again
        self.assertEqual((status, payload["id"]), (200, first))
        row = self.rows()[0]
        self.assertEqual((row["state"], row["album_id"]), ("applied", self.nd.only()["id"]))
        # Once: by the job the row belongs to.
        self.assertEqual(len(self.notified), 1)
        self.assertEqual(len(self.refreshed), 1)

    def test_two_requests_for_one_album_cannot_both_start(self):
        # "Is a job running for this album? Then this one is" is one step: a
        # second request waits for the first to have written its row.
        answers = []
        with bot._album_override_claim_lock:
            second = threading.Thread(target=lambda: answers.append(self.apply()))
            second.start()
            second.join(0.3)
            self.assertTrue(second.is_alive(), "it did not wait")
            self.assertEqual(self.rows(), [])
        second.join(10)
        self.assertEqual([status for _payload, status in answers], [200])

