    # ── which album is "the album again" ────────────────────────────────────

    def split(self):
        """Half the folder already says PLAIN, so Navidrome lists two albums
        in it. Returns the id of each half."""
        names = sorted(n for n in os.listdir(self.folder) if n.endswith(".flac"))
        for name in names[:6]:
            bot._mutagen_write_tags(os.path.join(self.folder, name), {"mb_albumid": PLAIN})
        self.nd.index()
        ids = {a["musicBrainzId"]: a["id"] for a in self.nd.albums.values()}
        return ids[LONERISM], ids[PLAIN]

    def test_an_album_is_not_the_one_until_it_holds_the_files_that_were_written(self):
        # Before any scan Navidrome already lists an album in the folder with
        # the chosen release: the half that said so all along. It is not the
        # retagged album — six of the twelve songs are not in it yet.
        old_half, plain_half = self.split()
        self.gap(old_half)
        self.nd.auto = False            # the scan is asked for and has not run
        self.at_wait[4] = self.nd.finish
        payload, status = self.apply(album_id=old_half)
        self.assertEqual(status, 200, payload)
        self.assertEqual(self.waits, [("applying", "")] * 4)
        whole = self.nd.only()
        self.assertEqual(len(whole["song"]), 12)
        row = self.rows()[0]
        self.assertEqual((row["state"], row["album_id"]), ("applied", whole["id"]))
        # The id the other half had is dead once the scan has ended, and that
        # is when it is looked at: its review group goes.
        self.assertNotIn(old_half, self.nd.albums)
        self.assertEqual([g["id"] for g in bot._review_snapshot()["groups"]], [])
        self.assertEqual([k["nd_album_ids"] for _m, k in self.notified], [[whole["id"]]])

    def test_the_album_is_found_by_the_files_it_holds(self):
        old_half, plain_half = self.split()
        paths = {a["musicBrainzId"]: [song["path"] for song in a["song"]]
                 for a in self.nd.albums.values()}
        find = lambda expect: (bot._nd_find_album_in_folder(
            self.folder, PLAIN, ("Lonerism",), expect) or {}).get("id")
        self.assertEqual(find(paths[PLAIN]), plain_half)
        self.assertEqual(find(()), plain_half)
        self.assertIsNone(find(paths[LONERISM]))
        self.assertIsNone(find(paths[PLAIN] + paths[LONERISM][:1]))

    def test_nothing_is_called_listed_before_a_scan_has_finished(self):
        # Every file already says the release, so the album Navidrome lists
        # holds them all — but what it lists is from before this job. Not
        # until a scan that began after the job's last write has ended.
        first = self.applied()
        self.waits.clear()
        self.notified.clear()
        self.nd.auto = False
        self.at_wait[2] = self.nd.finish
        again, status = self.apply(album_id=self.nd.only()["id"])
        self.assertEqual((status, again["id"]), (200, first))
        self.assertEqual(self.waits, [("applying", "")] * 2)
        self.assertEqual(self.rows()[0]["state"], "applied")
        self.assertEqual(len(self.notified), 1)

