    def test_an_undo_that_loses_the_folder_half_way_keeps_everything(self):
        # The folder was there when the undo was asked for and is not when the
        # task gets to it (a mount going away): every snapshot and the kept
        # cover stay, and the row still knows which cover is lb-bot's.
        original = self.original()
        before = self.tags()
        override_id = self.applied(cover_url=self.URL)
        moved = self.folder + " (2012)"
        os.rename(self.folder, moved)
        bot._album_override_remove_task(override_id)
        (row,) = self.rows()
        self.assertEqual((row["state"], row["done"], row["cover_file"], row["cover_url"]),
                         ("failed", 0, "cover.jpg", self.URL))
        failures = json.loads(row["failures"])
        self.assertEqual(len(failures), 13)
        self.assertEqual({f["reason"] for f in failures[:12]},
                         {"its folder is no longer there; its earlier tags are still kept"})
        self.assertEqual(failures[12], {"title": "Cover image",
                                        "reason": "the album's folder is no longer there"})
        self.assertEqual(len(self.snapshots()), 12)
        self.assertEqual(self.read(self.backups, override_id, "cover.jpg"), original)
        os.rename(moved, self.folder)
        self.assertEqual(bot._album_override_remove_view({"id": override_id})[1], 200)
        self.assertEqual(self.rows(), [])
        self.assertEqual((self.tags(), self.read(self.folder, "cover.jpg")), (before, original))

    def test_deleting_a_row_never_deletes_a_cover_still_kept_for_it(self):
        self.original()
