    def test_on_a_second_press_the_total_is_what_that_press_tries(self):
        # As for an album's remove (F7): a file given up on is not one the
        # press tries, and `done + failures >= total` has to come true.
        merge_id = self.merged()
        os.remove(os.path.join(self.strap, "02. Sleep the Clock Around.flac"))
        here = os.path.join(self.waitress, "02. Piazza, New York Catcher.flac")
        away = os.path.join(self.tmp, "away.flac")
        os.rename(here, away)
        bot._artist_merge_undo_view({"id": merge_id})
        row = self.row(merge_id)
        self.assertEqual((row["state"], row["done"], row["total"], len(row["failures"])),
                         ("failed", 3, 5, 2))
        os.rename(away, here)
        del self.waits[:]
        self.nd.auto = False
        seen = {}
        self.at_wait[1] = lambda: seen.update(self.rows()[0])
        self.at_wait[2] = self.nd.finish
        self.undo(merge_id)
        self.assertEqual((seen["state"], seen["done"], seen["total"], seen["failures"]),
                         ("undoing", 1, 1, "[]"))
        self.assertTrue(self.gone(merge_id))

