    def test_the_albums_are_claimed_and_fill_gaps_held_while_the_files_are_rewritten(self):
        album_id = self.gap("The Boy With the Arab Strap")
        seen = []
        real = bot._tag_restore

        def write(path, part):
            with bot._review_lock:
                held = bot._album_override_holds_group(bot._find_review_group("g1"))
            seen.append((bot._group_placement_active("g1"), held))
            return real(path, part)

        with patch.object(bot, "_tag_restore", write):
            merge_id = self.merged()
        self.assertEqual(set(seen), {(True, "an artist merge is rewriting this album's files — "
                                            "try again when it has finished")})
        self.assertFalse(bot._group_placement_active("g1"))
        self.assertFalse(bot._album_override_running_for({album_id}))
        # …and the undo holds them the same way (under the ids they have now).
        self.nd.index()
        with bot._review_lock:
            bot._review_state["groups"] = []
        self.gap("The Boy With the Arab Strap")
        seen.clear()
        real_restore = bot._tag_restore

        def restore(path, snapshot):
            with bot._review_lock:
                held = bot._album_override_holds_group(bot._find_review_group("g1"))
            seen.append((bot._group_placement_active("g1"), bool(held)))
            return real_restore(path, snapshot)

        with patch.object(bot, "_tag_restore", restore):
            self.undo(merge_id)
        self.assertEqual((len(seen), set(seen)), (5, {(True, True)}))
        self.assertFalse(bot._group_placement_active("g1"))

    def test_a_job_running_is_in_progress(self):
        before = self.files()
        for state in ("merging", "undoing"):
            with bot._index_lock, bot._index_db() as conn:
                conn.execute("DELETE FROM artist_merges")
                conn.execute("INSERT INTO artist_merges (id, state, into_nd_id, into_name, "
                             "from_nd_id, from_name, mbid, set_at) VALUES ('m1', ?, ?, ?, ?, ?, ?, 1)",
                             (state, self.kept_id, KEPT, self.variant_id, VARIANT, BELLE))
            # the same pair again, the pair the other way round, and its undo
            self.assertEqual(self.refused(*self.merge()), (409, "in_progress"))
            self.assertEqual(self.refused(*self.merge(nd_id=self.variant_id,
                                                      from_nd_id=self.kept_id)),
                             (409, "in_progress"))
            self.assertEqual(self.refused(*bot._artist_merge_undo_view({"id": "m1"})),
                             (409, "in_progress"))
        self.assertEqual((self.files(), len(self.rows())), (before, 1))

    def test_an_album_override_and_a_merge_do_not_run_on_the_same_album(self):
        (album,) = [a for a in self.nd.albums.values() if a["name"] == "Dear Catastrophe Waitress"]
        job = bot._album_override_job_begin({album["id"]})
        self.assertEqual(self.refused(*self.merge()), (409, "in_progress"))
        bot._album_override_job_end(job)
        # …and while a merge has the artist's albums, an override of one of them waits.
        seen = []
        real = bot._tag_restore

        def write(path, part):
            seen.append(bot._album_override_running_for({album["id"]}))
            return real(path, part)

        with patch.object(bot, "_tag_restore", write):
            self.merged()
        self.assertEqual(set(seen), {True})

    def test_a_job_that_dies_does_not_leave_the_row_merging(self):
        calls = []
        real_write = bot._tag_restore

        def write(path, part):
            calls.append(path)
            if len(calls) == 3:
                raise RuntimeError("the disk went away")
            return real_write(path, part)

        def task_run(kind, label, target, **k):
            try:
                target("t1")
            except Exception:  # noqa: BLE001 — as the real one: the error is the task's
                pass
            return "t1"

        album_id = self.gap("The Boy With the Arab Strap")
        before = self.files()
        with patch.object(bot, "_tag_restore", write), \
                patch.object(bot, "_task_run", task_run):
            merge_id = self.merged()
        row = self.row(merge_id)
        self.assertEqual((row["state"], row["done"], row["total"]), ("failed", 2, 5))
        self.assertEqual(row["failures"], [{
            "album": "", "title": VARIANT,
            "reason": "stopped by an error (RuntimeError) — undo to restore the previous tags, "
                      "or merge again"}])
        self.assertFalse(bot._group_placement_active("g1"))
        self.assertFalse(bot._album_override_running_for({album_id}))
        self.undo(merge_id)
        self.assertEqual(self.files(), before)

    def test_a_row_found_mid_task_at_startup_reads_failed(self):
        merge_id = self.merged()
        before_undo = self.files()
        for state in ("merging", "undoing"):
            with bot._index_lock, bot._index_db() as conn:
                conn.execute("UPDATE artist_merges SET state = ?, failures = '[]'", (state,))
            self.assertEqual(bot._artist_merges_interrupted(), 1)
            row = self.row(merge_id)
            self.assertEqual(row["state"], "failed")
            self.assertEqual(row["failures"], [{
                "album": "", "title": VARIANT,
                "reason": "interrupted by a restart — undo to restore the previous tags, "
                          "or merge again"}])
        self.assertEqual(bot._artist_merges_interrupted(), 0)
        self.assertEqual(self.files(), before_undo)
        self.undo(merge_id)
        self.assertTrue(self.gone(merge_id))

    def test_at_startup_each_kind_of_job_is_checked_on_its_own(self):
        # One check failing must not leave the other's rows reading as
        # running — `in_progress` to every request — until the next restart.
        with bot._index_lock, bot._index_db() as conn:
            conn.execute("INSERT INTO artist_merges (id, state, into_nd_id, into_name, "
                         "from_nd_id, from_name, mbid, set_at, failures) "
                         "VALUES ('m1', 'merging', ?, ?, ?, ?, ?, ?, '[]')",
                         (self.kept_id, KEPT, self.variant_id, VARIANT, BELLE, time.time()))
        out = io.StringIO()
        with patch.object(bot, "_album_overrides_interrupted",
                          side_effect=sqlite3.OperationalError("no such table")), \
                contextlib.redirect_stdout(out):
            bot._mark_interrupted_jobs()
        self.assertEqual(self.rows()[0]["state"], "failed")
        self.assertIn("album overrides: could not check", out.getvalue())
        # …and the other way round.
        with bot._index_lock, bot._index_db() as conn:
            conn.execute("UPDATE artist_merges SET state = 'undoing'")
        checked = []
        with patch.object(bot, "_artist_merges_interrupted", side_effect=RuntimeError("boom")), \
                patch.object(bot, "_album_overrides_interrupted", lambda: checked.append(1)), \
                contextlib.redirect_stdout(out):
            bot._mark_interrupted_jobs()
        self.assertEqual(checked, [1])
        self.assertIn("artist merges: could not check", out.getvalue())
        # It is what the start runs.
        import inspect
        self.assertIn("_mark_interrupted_jobs()", inspect.getsource(bot.main))
        self.assertNotIn("_artist_merges_interrupted()", inspect.getsource(bot.main))

