    # ── waiting for Navidrome, and what follows ─────────────────────────────

    def test_merged_waits_for_a_scan_that_began_after_the_last_write(self):
        self.nd.auto = False
        self.at_wait[3] = self.nd.finish
        merge_id = self.merged()
        self.assertEqual(self.waits, ["merging"] * 3)
        self.assertEqual(self.row(merge_id)["state"], "merged")
        self.assertEqual(len(self.notified), 1)

    def test_after_a_minute_it_is_merged_whatever_navidrome_is_doing(self):
        self.nd.auto = False
        wait = int(bot.ALBUM_OVERRIDE_INDEX_WAIT / bot.ALBUM_OVERRIDE_POLL_SECS)
        held = {}
        (album,) = [a for a in self.nd.albums.values() if a["name"] == "Dear Catastrophe Waitress"]
        running = lambda: bot._album_override_running_for({album["id"]})
        self.at_wait[wait] = lambda: held.setdefault("before", running())
        self.at_wait[wait + 1] = lambda: held.setdefault("after", running())
        self.at_wait[wait + 4] = self.nd.finish
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            merge_id = self.merged()
        self.assertEqual(self.waits[:wait], ["merging"] * wait)
        self.assertEqual(self.waits[wait:], ["merged"] * 4)
        # The album is let go of with the answer; the news follows the scan.
        self.assertEqual(held, {"before": True, "after": False})
        self.assertEqual((self.row(merge_id)["state"], len(self.notified)), ("merged", 1))

    def test_a_navidrome_that_never_scans_is_one_log_line(self):
        self.nd.auto = False
        out = io.StringIO()
        with contextlib.redirect_stdout(out):
            merge_id = self.merged()
        self.assertEqual((self.row(merge_id)["state"], self.notified), ("merged", []))
        self.assertIn("did not finish a scan", out.getvalue())
        self.assertNotIn(self.tmp, out.getvalue())
        # Nor is the artist scanned: there is nothing new to read.
        self.assertEqual(self.scans, [])

    def test_an_undo_ends_on_the_same_rule(self):
        merge_id = self.merged()
