    # ── J10: an override judges its own row and no other ─────────────────────

    def rows(self) -> dict:
        with bot._review_lock:
            return {r["title"]: json.loads(json.dumps(r))
                    for r in bot._find_review_group(self.GID)["missing_tracks"]}

    def lands_later(self, title, seconds) -> None:
        """A row whose file lands after the placement pass: it reads
        `downloaded` and waits for a placement of its own."""
        path = self.fetch(title, seconds=seconds, heard=[])
        with bot._review_lock:
            row = next(r for r in bot._find_review_group(self.GID)["missing_tracks"]
                       if r["title"] == title)
            row.update(decision="downloaded", local_path=path, downloaded_at=time.time())

    def not_yet(self, title) -> None:
        with bot._review_lock:
            row = next(r for r in bot._find_review_group(self.GID)["missing_tracks"]
                       if r["title"] == title)
            row.update(decision="pending", local_path="")
            row.pop("downloaded_at", None)

    def two_refused_and_one_waiting(self) -> dict:
        self.fetch("Requiem")
        self.fetch("Heartbeat", seconds=255, heard=_named((0.98, "Monochrome"), seconds=255))
        self.gap("Requiem", "Heartbeat", "Two Hands")
        self.not_yet("Two Hands")
        self.place_gap()
        self.lands_later("Two Hands", 202)
        before = self.rows()
        self.assertEqual([(before[t]["decision"], before[t].get("force_place_kind"))
                          for t in ("Requiem", "Heartbeat", "Two Hands")],
                         [("downloaded", "recording"), ("downloaded", "recording"),
                          ("downloaded", None)])
        return before

    def test_an_override_judges_its_own_row_and_no_other(self):
        """Two rows refused as another recording, each with its offer, and a
        third whose file has landed and waits for its placement. Pressing one
        row's "Place anyway" judged all three against the one-file import: the
        other two read `failed`, "no downloaded file matched", their offers
        gone."""
        before = self.two_refused_and_one_waiting()
        scans = []
        del self.verified[:]
        with patch.object(bot, "_nd_scan_after_import", lambda token: scans.append(token) or True):
            answer = self.anyway("Requiem")
        self.assertEqual((answer["status"], answer["ok"]), (200, True))
        after = self.rows()
        # Its own row: placed, as a row the poller's helper placed is.
        self.assertEqual(after["Requiem"]["decision"], "placed")
        self.assertGreaterEqual(after["Requiem"]["imported_at"],
                                before["Requiem"]["downloaded_at"])
        self.assertNotIn("download_error", after["Requiem"])
        self.assertNotIn("can_force_place", after["Requiem"])
        with bot._review_lock:
            self.assertEqual(bot._find_review_group(self.GID)["status"], "placed")
        self.assertEqual((self.verified, len(scans)), ([self.GID], 1))
        # Every other row: state, text, offer and file exactly as they were.
        for title in ("Heartbeat", "Two Hands"):
            self.assertEqual(after[title], before[title])
            self.assertTrue(os.path.isfile(after[title]["local_path"]))
        # So the second offer is still there to press,
        self.assertTrue(self.anyway("Heartbeat")["ok"])
        self.assertEqual(self.row("Heartbeat")["decision"], "placed")
        # and the waiting file is still the next placement's.
        self.assertEqual(self.rows()["Two Hands"], before["Two Hands"])
        self.assertEqual(self.place_gap()["placed"], 1)
        self.assertEqual(self.in_library(),
                         ["02 - Heartbeat.flac", "06 - Two Hands.flac", "08 - Requiem.flac"])

    def test_an_override_of_a_duplicate_leaves_a_waiting_row_alone(self):
        import shutil
