    def test_an_override_pops_no_album_group(self):
        # The rest of the album is still arriving from a peer: that transfer
        # group is its own finalize's to end, not one row's override's.
        saved = (dict(bot.pending_album_groups), dict(bot.pending_downloads))

        def restore():
            for live, old in zip((bot.pending_album_groups, bot.pending_downloads), saved):
                live.clear()
                live.update(old)

