        bot.pending_album_groups["ag-beat"] = {
            "review_group_id": self.GID, "source_user": "peer1", "total": 1, "completed": 0}
        bot.pending_downloads[("peer1", "x\\07 The Howler.flac")] = {
            "album_group_id": "ag-beat", "review_group_id": self.GID}
