    # ── J19: an override names the row it was shown for ──────────────────────

    ROW_MOVED = {"ok": False, "code": "row_moved",
                 "error": "This album's tracks were read again since the page was drawn "
                          "— open it again."}

    def press(self, index, shown=None, **sent):
        """`POST …/tracks/<index>/place-anyway` as a page that drew `shown`
        (a row of the gap view) sends it: the row's recording id and title."""
        if shown is not None:
            sent = {"json": {"recordingMbid": shown["recordingMbid"],
                             "title": shown["title"], **sent.get("json", {})}}
        r = _web_app().test_client().post(
            f"/api/groups/{self.GID}/tracks/{index}/place-anyway", **sent)
        return r.get_json(), r.status_code

    def drawn(self) -> dict:
        """Two rows refused as another recording, each with its offer, and
        the page as it was drawn of them."""
        self.fetch("Requiem")
        self.fetch("Heartbeat", seconds=255, heard=_named((0.98, "Monochrome"), seconds=255))
        self.gap("Requiem", "Heartbeat")
        self.place_gap()
        page = {t: self.wire(t) for t in ("Requiem", "Heartbeat")}
        self.assertEqual([(page[t]["index"], page[t]["canForcePlace"], page[t]["title"])
                          for t in ("Requiem", "Heartbeat")],
                         [(0, True, "Requiem"), (1, True, "Heartbeat")])
        self.assertEqual(page["Requiem"]["recordingMbid"], _uid(8))
        return page

    def read_again(self) -> None:
        """What a rescan between the view and the press can do: the rows are
        the same rows, at other indexes."""
        with bot._review_lock:
            bot._find_review_group(self.GID)["missing_tracks"].reverse()

    def test_an_override_names_the_row_it_was_shown_for(self):
        """The right row: placed as before, whatever case the id is sent in
        and however the title is spelled, with one of the two or with both."""
        for case, sent in (("as the page shows it", {}),
                           ("the title spelled otherwise", {"title": "  REQUIEM!"}),
                           ("the id alone", {"title": ""}),
                           ("the title alone", {"recordingMbid": ""})):
            with self.subTest(case):
                page = self.drawn()
                answer, status = self.press(0, page["Requiem"], json=sent)
                self.assertEqual((status, answer["ok"], sorted(answer)),
                                 (200, True, ["error", "import_result", "ok"]))
                self.assertEqual(self.row("Requiem")["decision"], "placed")
                self.assertEqual(self.row("Heartbeat")["decision"], "downloaded")
                self.assertEqual(self.in_library(), ["08 - Requiem.flac"])
                import shutil
                shutil.rmtree(os.path.join(self.lib, "King Crimson"))

    def test_an_override_at_a_shifted_index_places_nothing(self):
        """The index the page holds is another offered row's now. The press
        was confirmed against Requiem's refusal; it must not place
        Heartbeat's file."""
        page = self.drawn()
        self.read_again()
        before = self.rows()
        del self.verified[:]
        other = self.wire("Heartbeat")
        self.assertEqual((other["index"], other["canForcePlace"]), (0, True))
        for case, index, sent in (
                ("both, as the page shows them", 0, {}),
                ("the id alone", 0, {"title": ""}),
                ("the title alone", 0, {"recordingMbid": ""}),
                ("the id of the row there, the title of the row shown",
                 0, {"recordingMbid": other["recordingMbid"]}),
                ("the title of the row there, the id of the row shown",
                 0, {"title": other["title"]}),
                ("an index past the end", 2, {})):
            with self.subTest(case):
                answer, status = self.press(index, page["Requiem"], json=sent)
                self.assertEqual((status, answer), (409, self.ROW_MOVED))
                self.assertEqual(self.rows(), before)
                self.assertEqual(self.in_library(), [])
                for row in before.values():
                    self.assertTrue(os.path.isfile(row["local_path"]))
                self.assertEqual(self.verified, [])
        # Opened again, the page holds the row's index of now, and the press
        # is the row's.
        answer, status = self.press(self.wire("Requiem")["index"], self.wire("Requiem"))
        self.assertEqual((status, answer["ok"]), (200, True))
        self.assertEqual(self.in_library(), ["08 - Requiem.flac"])

    def test_an_override_that_names_no_row_is_as_before(self):
        """A client that sends nothing — a hub, a phone, an older page — is
        answered as it always was: by the index alone."""
        for case, sent in (("no body", {}), ("an empty one", {"json": {}}),
                           ("both empty", {"json": {"recordingMbid": "", "title": ""}}),
                           ("no object", {"json": ["Requiem"]}),
                           ("not JSON", {"data": "Requiem", "content_type": "text/plain"})):
            with self.subTest(case):
                self.drawn()
                self.read_again()
                answer, status = self.press(0, **sent)
                self.assertEqual((status, answer["ok"]), (200, True))
                # The row at that index now — Heartbeat's.
                self.assertEqual(self.in_library(), ["02 - Heartbeat.flac"])
                import shutil
                shutil.rmtree(os.path.join(self.lib, "King Crimson"))
        # An index no row has, with nothing sent: the answer it always got.
        self.drawn()
        answer, status = self.press(7)
        self.assertEqual((status, answer), (400, {"ok": False, "error": "Track index out of range"}))

    def test_the_row_a_page_shows_is_the_row_whatever_id_the_view_gave_it(self):
        """The gap view pairs a track the library lists with a missing row of
        the same title, and shows the row under the library's id — in the
        case Navidrome has it. The page sends what it shows; that is the row
        at its index, and the press is not turned away. Ids meet in one case
        on both sides (ids with letters in them: `_uid(n)`'s are digits)."""
        import shutil
        owned = _uid(808).replace("0", "A")
        self.assertNotEqual(owned, owned.lower())

        def shown() -> list:
            self.drawn()
            with bot._review_lock:
                group = bot._find_review_group(self.GID)
                group["albums"][0]["tracks"] = [
                    {"id": "s8", "title": "Requiem", "musicBrainzId": owned, "trackNumber": 8}]
                group["missing_tracks"][0]["recording_mbid"] = REC
                view = bot._gap_detail_view(group)
            return [r for r in view["tracks"] if r["title"] == "Requiem"]

        self.assertEqual([(r["index"], r["recordingMbid"], r["canForcePlace"]) for r in shown()],
                         [(0, owned, True), (0, _uid(8), True)])
        for case, sent in (("the library's id, as the view shows the row", owned),
                           ("the same in lower case", owned.lower()),
                           ("the id the view shows its own row under", _uid(8)),
                           ("the id the row carries", REC),
                           ("the same in upper case", f" {REC.upper()} ")):
            with self.subTest(case):
                shown()
                answer, status = self.press(0, json={"recordingMbid": sent, "title": "Requiem"})
                self.assertEqual((status, answer["ok"]), (200, True))
                self.assertEqual(self.in_library(), ["08 - Requiem.flac"])
                shutil.rmtree(os.path.join(self.lib, "King Crimson"))
        # An id that is none of the row's is another row's, whatever the title.
        shown()
        self.assertEqual(self.press(0, json={"recordingMbid": OTHER_REC, "title": "Requiem"}),
                         (self.ROW_MOVED, 409))
        self.assertEqual(self.in_library(), [])

